/* Ablenkungsideen – redigiert: Neugier & Können statt Beschäftigung */
D.stattDaddeln = [
  /* ---------- Lesen ---------- */
  {"id":"SD101","titel":"Der beste erste Satz","text":"Lies von fünf Büchern aus dem Regal nur den ersten Satz und küre den besten Romananfang. Der Sieger wird als Nächstes gelesen.","min":10,"tf":"ABC","kat":"Lesen","haltung":"im Sitzen","t":"lesen"},
  {"id":"SD201","titel":"Feuerkelch mit Wette","ab":[4,16],"text":"Lies das nächste Kapitel im „Feuerkelch“ und schreib vorher verdeckt auf, wer deiner Meinung nach Harrys Namen in den Kelch geworfen hat. Abgerechnet wird, wenn das Buch zu ist.","min":20,"tf":"ABCD","kat":"Lesen","haltung":"im Sitzen, im Liegen","t":"lesen"},
  {"id":"SD103","titel":"Zeitung von hinten","text":"Lies die Zeitung heute von der letzten Seite nach vorn und such die kurioseste Kurzmeldung. Die wird beim nächsten Telefonat erzählt.","min":15,"tf":"ABCD","kat":"Lesen","haltung":"im Sitzen","t":"lesen"},
  {"id":"SD104","titel":"Kaléko, zweimal laut","text":"Lies ein Gedicht von Mascha Kaléko laut, und dann gleich noch einmal mit ganz anderer Betonung. Welche Fassung hätte ihr besser gefallen? Ein guter Anfang ist „Sozusagen grundlos vergnügt“ – unten kannst du es dir auch vorlesen lassen.","min":5,"tf":"ABCD","kat":"Lesen","haltung":"im Sitzen, im Liegen","t":"lesen",
    "hoeren":[{"text": "Kaléko-Gedichte gelesen (YouTube)", "url": "https://www.youtube.com/results?search_query=Mascha+Kal%C3%A9ko+Gedichte+gelesen", "spotify": "Mascha Kaléko Gedichte"}, {"text": "„Sozusagen grundlos vergnügt“ (YouTube)", "url": "https://www.youtube.com/results?search_query=Mascha+Kal%C3%A9ko+Sozusagen+grundlos+vergn%C3%BCgt", "spotify": "Mascha Kaléko Sozusagen grundlos vergnügt"}],
    "links":[{"text": "Mascha Kaléko bei Wikipedia (Leben und Werke)", "url": "https://de.wikipedia.org/wiki/Mascha_Kal%C3%A9ko"}, {"text": "Kaléko-Bücher ausleihen: VÖBB digital", "url": "https://www.voebb.de/digitale-angebote"}]},
  {"id":"SD202","titel":"Was liest eigentlich Max?","text":"Frag Max, welches Buch er gerade liest, und lies die Leseprobe davon. Danach darfst du ihm eine ehrliche Kurzkritik schicken.","min":15,"tf":"ABC","kat":"Lesen","haltung":"im Sitzen, im Liegen","t":"lesen"},

  /* ---------- Hören ---------- */
  {"id":"SD109","titel":"Hörspiel mit Sternen","text":"Hör ein Hörspiel aus „ARD Sounds“ (früher ARD Audiothek, unten ein Knopf) und vergib danach Sterne für Stimmen, Geräusche und Schluss. Eine Kritikerin muss streng sein.","min":40,"tf":"ABCD","kat":"Hören","haltung":"im Sitzen, im Liegen","t":"hoerbuch",
    "hoeren":[{"text": "Hörspiele in ARD Sounds", "url": "https://www.ardsounds.de/rubrik/hoerspiel-112/", "spotify": "ARD Hörspiel"}, {"text": "Hörspiele auf YouTube", "url": "https://www.youtube.com/results?search_query=ARD+H%C3%B6rspiel+komplett"}]},
  {"id":"SD110","titel":"Zeitzeichen von heute","text":"Hör die heutige Folge „Zeitzeichen“ vom WDR, eine Viertelstunde über ein Ereignis von genau diesem Datum. Die überraschendste Zahl wird weitererzählt.","min":15,"tf":"ABCD","kat":"Hören","haltung":"im Sitzen, im Liegen","t":"radio",
    "hoeren":[{"text": "WDR Zeitzeichen in ARD Sounds", "url": "https://www.ardsounds.de/sendung/wdr-zeitzeichen/urn:ard:show:3cb325e2d310d798/", "spotify": "WDR Zeitzeichen"}, {"text": "Zeitzeichen auf YouTube", "url": "https://www.youtube.com/results?search_query=WDR+Zeitzeichen"}]},
  {"id":"SD111","titel":"Hörbuch auf Probe","text":"Hör eine Lesung aus einem Buch, das du nie selbst gekauft hättest. Nach 20 Minuten wird entschieden: weiter oder weg.","min":20,"tf":"ABCD","kat":"Hören","haltung":"im Liegen","t":"hoerbuch",
    "hoeren":[{"text": "Hörbücher in ARD Sounds", "url": "https://www.ardsounds.de/rubrik/hoerbuch-108/", "spotify": "Hörbuch"}, {"text": "KULT! – Klassiker als Hörbuch (ARD Sounds)", "url": "https://www.ardsounds.de/sendung/kult-klassiker-der-weltliteratur-als-hoerbuecher/urn:ard:show:5012a809f8b1971e/", "spotify": "KULT! Klassiker der Weltliteratur als Hörbücher"}]},
  {"id":"SD112","titel":"Radio auf gut Glück","text":"Stell einen Sender ein, den du noch nie gehört hast, und hör eine Weile rein. Klassik, Jazz oder Polnisch – alles gilt.","min":10,"tf":"ABCD","kat":"Hören","haltung":"im Sitzen, im Liegen","t":"radio"},
  {"id":"SD113","titel":"Täter vor der Halbzeit","text":"Wärmflasche, Decke und ein Krimi-Hörspiel. Nenn den Täter, bevor die Hälfte rum ist, und schreib den Namen verdeckt auf.","min":30,"tf":"BCD","kat":"Hören","haltung":"im Liegen","t":"hoerbuch",
    "hoeren":[{"text": "Krimis zum Einschlafen (ARD Sounds)", "url": "https://www.ardsounds.de/sammlung/krimis-einschlafen-102/", "spotify": "Krimi Hörspiel"}, {"text": "Auf der Spur – ARD-Ermittlerkrimis", "url": "https://www.ardsounds.de/sendung/auf-der-spur-ard-ermittlerkrimis/urn:ard:show:1b3dd6076b453726/", "spotify": "Auf der Spur ARD Ermittlerkrimis"}, {"text": "Kein Mucks! – Krimis mit Bastian Pastewka", "url": "https://www.ardsounds.de/sendung/kein-mucks-der-krimi-podcast-mit-bastian-pastewka/urn:ard:show:e01e22ff9344b2a4/", "spotify": "Kein Mucks Bastian Pastewka"}]},
  {"id":"SD203","titel":"Rufus Beck zählt mit","text":"Hör ein Kapitel aus dem „Feuerkelch“ in der Lesung von Rufus Beck, der jeder Figur eine eigene Stimme gibt. Zähl mit, wie viele verschiedene Stimmen er in einem Kapitel schafft.","min":25,"tf":"ABCD","kat":"Hören","haltung":"im Sitzen, im Liegen","t":"hoerbuch"},
  {"id":"SD204","titel":"Eine Stunde Geschichte","text":"Hör eine Folge „Eine Stunde History“ von Deutschlandfunk Nova zu einem Thema, von dem du keine Ahnung hast. Die beste Erkenntnis bekommt Max per Nachricht.","min":60,"tf":"ABCD","kat":"Hören","haltung":"im Sitzen, im Liegen","t":"radio",
    "hoeren":[{"text": "„Eine Stunde History“ suchen", "url": "https://www.google.com/search?q=Eine+Stunde+History+Deutschlandfunk+Nova", "spotify": "Eine Stunde History"}, {"text": "Ähnlich: „Alles Geschichte“ in ARD Sounds", "url": "https://www.ardsounds.de/sendung/alles-geschichte-der-history-podcast/urn:ard:show:fdb83c5530d71150/", "spotify": "Alles Geschichte Der History-Podcast"}]},

  /* ---------- Musik ---------- */
  {"id":"SD117","titel":"„Summertime“, drei Fassungen","text":"Hör „Summertime“ von Ella Fitzgerald, Janis Joplin und einer dritten Stimme deiner Wahl. Wer gewinnt?","min":12,"tf":"ABCD","kat":"Musik","haltung":"im Sitzen, im Liegen","t":"musik",
    "hoeren":[{"text": "Ella Fitzgerald (YouTube)", "url": "https://www.youtube.com/results?search_query=Ella+Fitzgerald+Summertime", "spotify": "Summertime Ella Fitzgerald"}, {"text": "Janis Joplin (YouTube)", "url": "https://www.youtube.com/results?search_query=Janis+Joplin+Summertime", "spotify": "Summertime Janis Joplin"}, {"text": "Weitere Fassungen (YouTube)", "url": "https://www.youtube.com/results?search_query=Summertime+Gershwin", "spotify": "Summertime Gershwin"}]},
  {"id":"SD121","titel":"Endlich verstehen, wovon das Lied handelt","text":"Such dir ein Lied auf Englisch, Französisch oder Italienisch, das du seit Jahren mitsummst, und lies nach, worum es wirklich geht. Manchmal ist ein Schlager in Wahrheit ein Drama.","min":10,"tf":"ABCD","kat":"Musik","haltung":"im Sitzen, im Liegen","t":"musik",
    "schritte":["Lied aussuchen – Vorschläge stehen unten.","In Google „Liedtitel + Übersetzung“ eingeben, oder ChatGPT fragen: „Worum geht es in ‚…‘? Erklär mir die wichtigsten Zeilen auf Deutsch.“","Das Lied noch einmal hören, jetzt mit Durchblick.","Eine Zeile, die dich überrascht hat, ins Tagebuch."],
    "optionen":["„Volare“ – Domenico Modugno","„La Mer“ – Charles Trenet","„Ne me quitte pas“ – Jacques Brel","„Azzurro“ – Adriano Celentano","„Hotel California“ – Eagles","„Bridge over Troubled Water“ – Simon & Garfunkel","Ein Lied aus dem Radio von heute"],
    "hoeren":[{"text": "„Volare“ (YouTube)", "url": "https://www.youtube.com/results?search_query=Volare+Domenico+Modugno", "spotify": "Volare Domenico Modugno"}, {"text": "„La Mer“ (YouTube)", "url": "https://www.youtube.com/results?search_query=La+Mer+Charles+Trenet", "spotify": "La Mer Charles Trenet"}, {"text": "„Ne me quitte pas“ (YouTube)", "url": "https://www.youtube.com/results?search_query=Ne+me+quitte+pas+Jacques+Brel", "spotify": "Ne me quitte pas Jacques Brel"}]},
  {"id":"SD126","titel":"Ein Klavierstück, blind","text":"Hör drei kurze Klavierstücke und rate jeweils: Bach, Chopin oder Satie? Die Auflösung erst danach lesen.","min":12,"tf":"ABCD","kat":"Musik","haltung":"im Liegen","t":"musik",
    "hoeren":[{"text": "Klavierstücke auf YouTube", "url": "https://www.youtube.com/results?search_query=ber%C3%BChmte+Klavierst%C3%BCcke+Klassik", "spotify": "Klassik Klavier"}]},

  /* ---------- Sinne ---------- */
  {"id":"SD134","titel":"Wolken bestimmen wie beim Wetterdienst","text":"Schau in den Himmel über dem Forst und bestimm, welche Wolken da ziehen. Wer sie kennt, weiß oft schon vor dem Radio, was das Wetter vorhat.","min":5,"tf":"ABCD","kat":"Sinne","haltung":"im Sitzen, im Liegen","t":"licht",
    "schritte":["Erst die Höhe schätzen: tief, mittel oder ganz hoch?","Dann die Form: Ballen, gleichmäßige Schicht oder feine Fäden?","Mit den Kärtchen unten vergleichen.","Ins Tagebuch: Wolke und Uhrzeit – und morgen prüfen, ob das Wetter kam."],
    "optionen":["Haufenwolke (Cumulus): weiße Blumenkohl-Ballen mit flacher Unterseite – Schönwetter","Schäfchenwolke (Altocumulus): viele kleine Ballen in mittlerer Höhe, wie eine Herde – Bonuspunkte","Federwolke (Cirrus): feine weiße Fäden ganz oben, aus Eiskristallen – oft kommt in ein, zwei Tagen ein Wetterwechsel","Schleierwolke (Cirrostratus): milchiger Schleier, manchmal mit Ring um die Sonne","Schichtwolke (Stratus): tiefer grauer Deckel ohne Form – der Berliner Novemberklassiker","Regenwolke (Nimbostratus): dick und dunkelgrau, es regnet oder gleich","Gewitterwolke (Cumulonimbus): riesiger Turm, oben breit wie ein Amboss – rein mit dir","Heute keine Wolken – Himmel blau, Punkte gibt’s trotzdem"]},
  {"id":"SD205","titel":"Polarstern finden","text":"Such abends vom Balkon den Großen Wagen und finde mit einem Trick den Polarstern. Danach weißt du ohne Handy, wo Norden ist.","min":10,"tf":"ABC","kat":"Sinne","haltung":"im Sitzen, im Stehen","t":"licht",
    "optionen":["Großer Wagen: sieben helle Sterne, ein Kasten mit Deichsel – im Herbst abends eher tief im Norden","Polarstern: die hintere Kante des Kastens fünfmal verlängern","Kassiopeia: ein großes W auf der anderen Seite des Polarsterns","Orion: drei Gürtelsterne in einer Reihe – ab Spätherbst spätabends im Südosten","Heute bewölkt – dann eben Wolken bestimmen"]},
  {"id":"SD206","titel":"Die Gewürz-Sommelière","text":"Füll fünf Gewürze in Eierbecher, misch sie mit geschlossenen Augen durch und rate jedes am Geruch. Jeder Treffer zählt, und die Nase wird mit jeder Runde besser.","min":10,"tf":"ABC","kat":"Sinne","haltung":"im Sitzen","t":"frei"},

  /* ---------- Körper (Kraft & Muskeln) ---------- */
  {"id":"SD207","titel":"Der Stuhl-Rekord","text":"Wie oft kommst du in 30 Sekunden vom Stuhl hoch? Das ist ein echter Fitness-Test, den auch Sportwissenschaftler nutzen – deine Zahl gehört nur dir, und in vier Wochen ist sie meist schon höher.","min":5,"tf":"ABC","kat":"Körper","haltung":"im Sitzen, im Stehen","t":"gymnastik",
    "schritte":["Einen festen Stuhl ohne Rollen an die Wand stellen.","Vorn auf die Kante setzen, Arme vor der Brust kreuzen. Lieber mit den Händen abstützen? Geht auch – dann eben immer so.","Aufstehen bis ganz gerade, wieder hinsetzen – 30 Sekunden lang zählen.","Die Zahl mit Datum ins Tagebuch. In vier Wochen wird nachgemessen."]},
  {"id":"SD208","titel":"Hanteln aus der Speisekammer","text":"Zwei volle Wasserflaschen sind die billigsten Hanteln Spandaus. Zehn Minuten im Sitzen, und die Arme wissen, dass sie gebraucht werden.","min":10,"tf":"ABCD","kat":"Körper","haltung":"im Sitzen","t":"gymnastik",
    "schritte":["Zwei volle 0,5-Liter-Flaschen nehmen (später 1-Liter, wenn’s zu leicht wird).","Aufrecht sitzen, Ellbogen am Körper: Flaschen langsam zur Schulter heben und senken – 10-mal.","Flaschen über den Kopf drücken und langsam zurück – 8-mal.","Eine Minute Pause, dann alles noch einmal."]},
  {"id":"SD209","titel":"Beinstrecker in der Werbepause","text":"Kräftige Oberschenkel sind das, was einen später leicht aus jedem Sessel hebt. Diese Übung geht im Sitzen, gern während der Werbung.","min":5,"tf":"ABCD","kat":"Körper","haltung":"im Sitzen","t":"gymnastik",
    "schritte":["Aufrecht auf einen Stuhl setzen, Hände an die Sitzfläche.","Ein Bein strecken, bis das Knie gerade ist, Fußspitze zu dir ziehen.","Drei Sekunden halten, langsam absenken.","10-mal pro Bein, zwei Runden."]},
  {"id":"SD210","titel":"Rudern mit dem Theraband","text":"Ein Theraband (gibt’s in Drogerie oder Sportgeschäft) ist ein Fitnessstudio in der Schublade. Rudern im Sitzen stärkt Rücken und Schultern.","min":8,"tf":"ABCD","kat":"Körper","haltung":"im Sitzen","t":"gymnastik",
    "schritte":["Aufrecht sitzen, Beine gestreckt oder Füße flach auf dem Boden.","Das Band um die Fußsohlen legen, die Enden in beide Hände.","Ellbogen eng am Körper nach hinten ziehen, Schulterblätter zusammen – kurz halten.","Langsam zurück. 12-mal, zwei Runden."]},
  {"id":"SD211","titel":"Wadenheben beim Zähneputzen","text":"Zwei Minuten Zähneputzen sind zwei Minuten Wadentraining, wenn du dich dabei an der Kante festhältst. Der Trick heißt: an etwas dranhängen, das du sowieso machst.","min":2,"tf":"AB","kat":"Körper","haltung":"im Stehen","t":"gleichgewicht",
    "schritte":["Mit einer Hand am Waschbecken festhalten.","Langsam auf die Zehenspitzen, kurz halten, langsam runter.","So lange, wie die Zahnbürste läuft."]},
  {"id":"SD212","titel":"EMS-Probetraining anfragen","text":"Max schwört drauf: 20 Minuten Training mit Strom-Weste, ein Trainer nur für dich. Frag in Spandau ein Probetraining an – anfragen kostet nichts.","min":10,"tf":"AB","kat":"Körper","haltung":"im Sitzen","t":"telefon",
    "schritte":["In Spandau gibt es zum Beispiel ein Bodystreet-Studio in der Klosterstraße (Knopf unten). Oder in Google Maps „EMS Training Spandau“ suchen und vergleichen.","Anrufen oder das Kontaktformular nutzen: „Ich möchte ein Probetraining machen. Was kostet es, was bringe ich mit?“","Deine Fragen von der Liste „Fragen fürs EMS-Studio“ danebenlegen.","Termin ins Papier-Tagebuch – und Max Bescheid sagen, er will alles wissen."],
    "links":[{"text":"Bodystreet Spandau (Klosterstraße)","url":"https://www.bodystreet.com/de/studio/bodystreet-berlin-spandau-klosterstrasse"}]},
  {"id":"SD213","titel":"Fragen fürs EMS-Studio","text":"Bevor du ins EMS-Studio gehst, schreib dir deine Fragen auf, so wie eine Reporterin vor dem Interview. Wer fragt, bestimmt das Tempo.","min":10,"tf":"ABC","kat":"Körper","haltung":"im Sitzen, im Liegen","t":"tagebuch",
    "optionen":["Ist der Trainer die ganze Zeit nur für mich da?","Wie oft pro Woche ist für den Anfang sinnvoll?","Was kostet es nach dem Probetraining – und wie lange läuft ein Vertrag?","Gibt es vorher einen Gesundheits-Fragebogen?","Was ziehe ich an, was bringe ich mit?","Kann ich mit wenig Strom anfangen und mich steigern?"]},

  /* ---------- Essen ---------- */
  {"id":"SD214","titel":"Wie viel Eiweiß brauchst du?","text":"Muskeln wollen Eiweiß, und ab 65 eher mehr als weniger. Rechne aus, wie viel es bei dir ist, und prüf, ob es gestern gereicht hat.","min":10,"tf":"ABC","kat":"Essen","haltung":"im Sitzen","t":"gelernt",
    "schritte":["Faustregel der Deutschen Gesellschaft für Ernährung ab 65: Körpergewicht in kg × 1 = Gramm Eiweiß pro Tag. Bei 62 kg also etwa 62 g.","Die europäische Fachgesellschaft ESPEN empfiehlt Älteren 1,0 bis 1,2 g pro kg – bei 62 kg also 62 bis 74 g.","Schreib auf, was du gestern gegessen hast, und rechne mit den Kärtchen unten grob zusammen.","Reicht’s? Wenn nicht: Wo passt morgen ein Quark, ein Ei oder ein Stück Käse hinein?"],
    "optionen":["250 g Magerquark: etwa 30 g","150 g Skyr: etwa 16 g","1 Ei: etwa 7 g","2 Scheiben Gouda (40 g): etwa 10 g","125 g Fischfilet: etwa 23–25 g","200 g gekochte Linsen: etwa 18 g","50 g Haferflocken: etwa 7 g","1 Glas Milch (200 ml): etwa 7 g"]},
  {"id":"SD215","titel":"Eiweiß auf drei Teller verteilt","text":"Für die Muskeln ist es günstiger, Eiweiß über den Tag zu verteilen, als abends alles auf einmal zu essen. Plan einen Tag mit je 20 bis 30 g pro Mahlzeit.","min":10,"tf":"ABC","kat":"Essen","haltung":"im Sitzen","t":"gelernt",
    "schritte":["Frühstück, etwa 28 g: 40 g Haferflocken mit 200 ml Milch und 150 g Skyr, dazu Obst.","Mittag, etwa 27 g: 125 g Fischfilet mit Kartoffeln und Gemüse – oder eine Linsensuppe.","Abend, etwa 23 g: zwei Scheiben Brot mit Käse und ein Ei.","Deinen eigenen Plan auf einen Zettel schreiben und an den Kühlschrank hängen."]},
  {"id":"SD216","titel":"Etiketten-Detektivin","text":"Nimm fünf Sachen aus dem Kühlschrank und lies auf der Packung ab, wie viel Eiweiß 100 Gramm haben. Mach eine Rangliste – der Sieger überrascht oft.","min":10,"tf":"ABC","kat":"Essen","haltung":"im Sitzen, im Stehen","t":"gelernt"},
  {"id":"SD217","titel":"Kräuterquark wie von früher, aber mit Plan","text":"250 g Magerquark bringen rund 30 g Eiweiß mit und schmecken mit Kräutern nach Sommer. Dazu Pellkartoffeln, fertig ist ein Muskel-Mittag.","min":15,"tf":"ABC","kat":"Essen","haltung":"im Stehen","t":"kochen",
    "schritte":["250 g Magerquark mit einem Schuss Milch oder Mineralwasser cremig rühren.","Schnittlauch und Petersilie klein schneiden, nach Lust eine halbe Knoblauchzehe dazu.","Mit Salz, Pfeffer und einem Spritzer Zitrone abschmecken.","Dazu Pellkartoffeln oder Vollkornbrot."]},
  {"id":"SD218","titel":"Rote Linsen in 15 Minuten","text":"Rote Linsen brauchen kein Einweichen, sind nach einer Viertelstunde weich und stecken voller Eiweiß. Eine Suppe, die nach mehr Arbeit schmeckt, als sie war.","min":25,"tf":"ABC","kat":"Essen","haltung":"im Stehen","t":"kochen",
    "schritte":["Eine Zwiebel und eine Möhre klein würfeln, in etwas Öl andünsten.","150 g rote Linsen und 750 ml Gemüsebrühe dazugeben.","15 Minuten köcheln lassen, bis die Linsen zerfallen.","Pürieren oder so lassen, mit Kreuzkümmel, Salz und Zitronensaft abschmecken. Ein Klecks Joghurt obendrauf."]},

  /* ---------- Handy ---------- */
  {"id":"SD219","titel":"Audible-Konto anlegen, Schritt für Schritt","text":"Ein Hörbuch-Konto, damit dir Rufus Beck den „Feuerkelch“ vorliest, wann du willst. Die Einrichtung dauert eine Viertelstunde, die Schritte stehen unten.","min":15,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"erstesmal",
    "schritte":["Auf dem Handy Chrome öffnen und audible.de aufrufen (erster Knopf unten).","Auf „Kostenlos testen“ tippen. Die ersten 30 Tage sind gratis, danach kostet Audible Standard 6,99 € im Monat (Stand Oktober 2026) und ist monatlich kündbar. Den aktuellen Preis zeigt die Seite.","Audible gehört zu Amazon: Mit deinem Amazon-Konto anmelden oder auf der Anmeldeseite ein neues Konto anlegen (Name, E-Mail, Passwort).","Eine Zahlungsart eingeben und bestätigen. Belastet wird erst nach dem Probemonat.","Tag 28 ins Tagebuch schreiben: „Audible – weiter oder kündigen?“ Kündigen geht auf audible.de unter „Abo kündigen“.","Jetzt die Audible-App aus dem Play Store installieren (zweiter Knopf) und mit denselben Daten anmelden.","Hörbuch aussuchen, am bequemsten auf audible.de im Browser. Unser Tipp: „Harry Potter und der Feuerkelch“, gelesen von Rufus Beck.","In der App unter „Bibliothek“ den Titel antippen. Er wird heruntergeladen und läuft dann auch ohne Internet. Wenn’s hakt: Bildschirmfoto an Max."],
    "links":[{"text":"audible.de öffnen","url":"https://www.audible.de/"},{"text":"Audible im Play Store","url":"https://play.google.com/store/apps/details?id=com.audible.application"}]},
  {"id":"SD220","titel":"Voi, diesmal ganz allein bedient","text":"Beim ersten Mal hat jemand geholfen, jetzt bedienst du die Voi-App selbst, vom Finden bis zum Parkfoto. Eine kurze Runde reicht.","min":20,"tf":"A","kat":"Handy","haltung":"unterwegs","t":"eroller",
    "schritte":["Voi-App öffnen: Die Karte zeigt die Roller in deiner Nähe.","Zum Roller gehen, in der App auf „Scannen“ tippen und den QR-Code am Lenker scannen.","Langsam anfahren, eine kleine ruhige Runde. Helm auf, wenn du einen hast.","Ordentlich abstellen, in der App „Fahrt beenden“ und das Parkfoto machen.","Ins Tagebuch: Minuten, Strecke, Preis. Wie fühlt sich Selbermachen an?"],
    "links":[{"text":"Voi im Play Store","url":"https://play.google.com/store/apps/details?id=io.voiapp.voi"}]},
  {"id":"SD221","titel":"Der Forst als Offline-Karte","text":"Lad dir den Spandauer Forst als Karte aufs Handy, die auch ohne Netz funktioniert. Zwischen den Kiefern ist der Empfang nämlich oft eher Gerücht.","min":10,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"gelernt",
    "schritte":["Google Maps öffnen. Du musst online und angemeldet sein, am besten im WLAN.","Oben nach „Spandauer Forst“ suchen.","Oben rechts auf die drei Punkte tippen, dann auf „Offlinekarte herunterladen“.","Den Ausschnitt mit den Fingern zurechtschieben und auf „Download“ tippen.","Probe: Flugmodus an, Karte öffnen – sie ist trotzdem da. Flugmodus wieder aus."]},
  {"id":"SD222","titel":"Pflanzen bestimmen mit Google Lens","text":"Halt die Handykamera auf ein Blatt oder eine Blüte, und Google Lens sagt dir, was das ist. Fünf Pflanzen vom Balkon oder vom Weg, dann hast du ein eigenes Herbarium.","min":15,"tf":"ABC","kat":"Handy","haltung":"im Sitzen, im Stehen","t":"natur",
    "schritte":["Google Lens öffnen: als eigene App oder über das bunte Kamera-Symbol in der Google-Suchleiste.","Die Kamera nah auf Blatt oder Blüte halten und den Auslöser tippen.","Ergebnis lesen und gegenprüfen: Passen Blattform und Farbe wirklich?","Namen ins Tagebuch, am besten mit kleiner Skizze."],
    "links":[{"text":"Google Lens im Play Store","url":"https://play.google.com/store/apps/details?id=com.google.ar.lens"}]},
  {"id":"SD223","titel":"Übersetzen mit der Kamera","text":"Halt die Kamera auf italienischen, französischen oder englischen Text, und das Handy übersetzt ihn direkt im Bild. Zauberei, die tatsächlich funktioniert.","min":10,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"erstesmal",
    "schritte":["Die App „Google Übersetzer“ installieren (Knopf unten) und öffnen.","Auf „Kamera“ tippen und die Kamera erlauben.","Oben die Sprachen wählen, zum Beispiel „Sprache erkennen“ → „Deutsch“.","Kamera über einen Text halten: Nudelpackung, Weinetikett, ein englisches Buch. Die Übersetzung erscheint direkt darüber."],
    "links":[{"text":"Google Übersetzer im Play Store","url":"https://play.google.com/store/apps/details?id=com.google.android.apps.translate"}]},
  {"id":"SD224","titel":"Diktieren statt tippen","text":"Sprich eine Nachricht an Max einfach ins Handy, und es schreibt mit, sogar die Kommas. Die lustigste Fehlerkennung darfst du stehen lassen.","min":5,"tf":"ABC","kat":"Handy","haltung":"im Sitzen, im Liegen","t":"erstesmal",
    "schritte":["Eine Nachricht an Max öffnen, so dass die Tastatur erscheint.","In der Tastatur auf das kleine Mikrofon tippen.","Deutlich sprechen. Satzzeichen sagst du mit: „Komma“, „Punkt“, „Fragezeichen“.","Vor dem Absenden einmal lesen, dann ab damit."]},
  {"id":"SD225","titel":"Erinnerung per Zuruf","text":"Sag deinem Handy, woran es dich morgen erinnern soll, und es piept pünktlich. Eine Sekretärin, die nie Feierabend macht.","min":5,"tf":"ABC","kat":"Handy","haltung":"im Sitzen, im Liegen","t":"erstesmal",
    "schritte":["„Hey Google“ sagen oder in der Google-Suchleiste auf das Mikrofon tippen. Bei manchen Handys geht es auch, wenn man die Ein-/Aus-Taste lange drückt.","Sagen: „Erinnere mich morgen um 10 Uhr, die Blumen zu gießen.“","Die Bestätigung auf dem Bildschirm prüfen.","Antwortet das Handy, dass es das nicht kann? Dann klappt es sicher über die Uhr-App: Wecker stellen und ihm einen Namen geben."]},
  {"id":"SD226","titel":"Schrift so groß, wie du willst","text":"Niemand muss sich am Handy die Augen verbiegen: Die Schriftgröße lässt sich mit einem Regler einstellen. Probier aus, was dir am besten gefällt.","min":5,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"gelernt",
    "schritte":["„Einstellungen“ öffnen (das Zahnrad).","Oben in die Suche „Schriftgröße“ eintippen und den Treffer öffnen.","Den Regler schieben, bis Nachrichten bequem lesbar sind. Daneben gibt es oft „Anzeigegröße“ oder „Bildschirmzoom“ für Knöpfe und Bilder.","Zu groß geraten? Einfach zurückschieben, kaputt geht nichts."]},
  {"id":"SD227","titel":"Ein Fotoalbum für Max","text":"Leg in Google Fotos ein gemeinsames Album an, in das du und Max Bilder legen könnt, zum Beispiel „Spandau im Herbst“. Fotos verschicken auf die elegante Art.","min":10,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"foto",
    "schritte":["Google Fotos öffnen.","Ein Foto lange antippen, dann weitere dazu antippen.","Oben auf „+“ tippen, „Album“ wählen und einen Namen geben.","Im Album auf „Teilen“ tippen und Max auswählen oder den Link schicken.","Max kann jetzt eigene Bilder dazulegen. Mal sehen, wer fleißiger ist."],
    "links":[{"text":"Google Fotos im Play Store","url":"https://play.google.com/store/apps/details?id=com.google.android.apps.photos"}]},
  {"id":"SD228","titel":"QR-Code-Jagd","text":"Die kleinen schwarzweißen Kästchen sind überall, auf Joghurtbechern, in der Zeitung, an Plakaten. Scann heute drei und find heraus, was dahintersteckt.","min":10,"tf":"ABC","kat":"Handy","haltung":"im Sitzen, unterwegs","t":"erstesmal",
    "schritte":["Die normale Kamera-App öffnen und auf den QR-Code richten.","Oben oder unten erscheint ein Link, den antippst du.","Kein Link? Dann klappt es mit Google Lens.","Ins Tagebuch: Welcher Code hatte das Beste dahinter?"]},
  {"id":"SD229","titel":"Wann kommt der Bus?","text":"Mit der BVG-App siehst du vom Sofa aus, wann der nächste Bus fährt, und musst nicht an der Haltestelle frieren. Deine Lieblingshaltestelle wird gleich Favorit.","min":10,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"gelernt",
    "schritte":["Die App „BVG Fahrinfo“ installieren (Knopf unten).","Beim ersten Start den Standort erlauben.","Den Reiter mit den Abfahrten in der Nähe öffnen. Da steht live, was gleich fährt.","Deine Haltestelle mit dem Stern als Favorit speichern.","Bonus: Eine Verbindung zu einem Ausflugsziel suchen, etwa zur Zitadelle."],
    "links":[{"text":"BVG Fahrinfo im Play Store","url":"https://play.google.com/store/apps/details?id=de.eos.uptrade.android.fahrinfo.berlin"}]},
  {"id":"SD230","titel":"Einen Podcast abonnieren","text":"Merk dir in der App „ARD Sounds“ eine Sendung, und jede neue Folge liegt automatisch für dich bereit. Wie ein Zeitungsabo, nur zum Hören.","min":10,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"erstesmal",
    "schritte":["„ARD Sounds“ (früher ARD Audiothek) aus dem Play Store installieren.","Über die Suche „Zeitzeichen“ finden, oder ein Hörspiel, das dich reizt.","Die Sendung mit dem Merken-Symbol speichern.","Eine Folge herunterladen. Dann läuft sie auch ohne Internet."],
    "links":[{"text":"ARD Sounds im Play Store","url":"https://play.google.com/store/apps/details?id=de.ard.audiothek"}],
    "hoeren":[{"text": "Zum Ausprobieren: Zeitzeichen in ARD Sounds", "url": "https://www.ardsounds.de/sendung/wdr-zeitzeichen/urn:ard:show:3cb325e2d310d798/", "spotify": "WDR Zeitzeichen"}]},
  {"id":"SD231","titel":"Drei gute Fragen an ChatGPT","text":"Stell ChatGPT heute drei Fragen, die du schon lange klären wolltest. Eine davon darf ruhig frech sein.","min":10,"tf":"ABC","kat":"Handy","haltung":"im Sitzen, im Liegen","t":"gelernt",
    "schritte":["ChatGPT-App öffnen (oder chatgpt.com im Browser).","Eine Frage eintippen oder mit dem Mikrofon sprechen. Vorschläge stehen unten.","Nachhaken ist erlaubt: „Erklär das einfacher“ oder „Gib mir ein Beispiel“.","Die beste Antwort ins Tagebuch. Wichtige Fakten lieber noch einmal gegenprüfen."],
    "links":[{"text":"ChatGPT im Play Store","url":"https://play.google.com/store/apps/details?id=com.openai.chatgpt"}],
    "optionen":["Warum heißt der Juliusturm eigentlich Juliusturm?","Was koche ich aus Quark, Lauch und zwei Eiern?","Erklär mir Quidditch in fünf Sätzen.","Schreib mir einen Limerick über Spandau.","Wie sage ich auf Italienisch höflich, dass die Suppe kalt ist?","Wie viel Eiweiß haben 200 g Kichererbsen?"]},
  {"id":"SD232","titel":"Zwei KI-Apps, eine Frage","text":"Stell ChatGPT und einer zweiten KI-App dieselbe Frage. Du bist die Jury: Wer erklärt besser, wer ist witziger?","min":15,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"erstesmal",
    "schritte":["Im Play Store eine zweite KI-App aussuchen, zum Beispiel Gemini, Le Chat oder Claude (Knopf unten).","Mit einer E-Mail-Adresse oder deinem Google-Konto anmelden.","Dieselbe Frage stellen, die du ChatGPT gestellt hast.","Punkte vergeben für Verständlichkeit, Witz und Nützlichkeit. Das Ergebnis bekommt Max."],
    "links":[{"text":"KI-Apps im Play Store","url":"https://play.google.com/store/search?q=KI%20Assistent&c=apps"}]},

  /* ---------- Geschichte ---------- */
  {"id":"SD162","titel":"Der Goldschatz im Juliusturm","text":"Ab 1874 lagerte im Juliusturm der Reichskriegsschatz: Goldmünzen im Wert von 120 Millionen Mark, bis 1914. Find heraus, warum die Bonner Politik in den 1950ern noch einmal einen „Juliusturm“ hatte.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD233","titel":"Spandau ist älter als Berlin","text":"Spandau bekam 1232 das Stadtrecht, Berlin taucht erst 1244 in einer Urkunde auf, und eingemeindet wurde Spandau erst 1920. Erzähl das beim nächsten Telefonat jemandem aus Berlin-Mitte und genieß den Moment.","min":5,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"telefon"},
  {"id":"SD234","titel":"Der Hauptmann mit Quittung","text":"1906 besetzte der Schuster Wilhelm Voigt in einer Trödel-Uniform das Rathaus Köpenick und ließ sich die Stadtkasse geben. Find heraus, was er dafür ausgestellt hat – es ist sehr preußisch.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD235","titel":"Die Ampel mit Polizist drin","text":"Eine der ersten Verkehrsampeln Europas stand 1924 am Potsdamer Platz, als Turm, in dem ein Polizist saß und schaltete. Ein Nachbau steht noch heute dort – such ihn beim nächsten Ausflug, oder erst mal ein Foto im Netz.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD236","titel":"Currywurst mit Patent","text":"Herta Heuwer erfand 1949 an ihrem Imbiss in Charlottenburg die Currywurst und ließ ihre Soße später als „Chillup“ eintragen. Rate, wo genau der Imbiss stand, und schlag es dann nach.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD237","titel":"Der erste Computer kam aus Kreuzberg","text":"1941 stellte Konrad Zuse in Berlin die Z3 vor, den ersten funktionierenden programmierbaren Computer. Frag ChatGPT, wie viel schneller dein Handy rechnet – die Zahl ist absurd.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD238","titel":"Zehntausend Untermieter in der Zitadelle","text":"In den Gewölben der Zitadelle Spandau überwintern jedes Jahr über zehntausend Fledermäuse, eines der größten Quartiere Europas. Find heraus, welche Arten dort hängen, und erzähl es weiter.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD239","titel":"Ich bin ein Pfannkuchen?","text":"Angeblich hat Kennedy 1963 mit „Ich bin ein Berliner“ gesagt, er sei ein Krapfen. Find heraus, warum das ein Märchen ist, und erklär es Max.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"telefon"},
  {"id":"SD240","titel":"Die Rache des Papstes","text":"Kaum stand 1969 der Fernsehturm, warf die Sonne ein leuchtendes Kreuz auf seine Kugel, sehr zum Ärger der DDR-Führung. Find heraus, welchen Spitznamen die Berliner dafür hatten.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD147","titel":"Was war hier früher?","text":"Such dir ein Haus in der Spandauer Altstadt aus und find heraus, was früher darin war. Das Gotische Haus in der Breiten Straße gilt als eines der ältesten Wohnhäuser Berlins, ein guter Anfang.","min":15,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},

  /* ---------- Lernen ---------- */
  {"id":"SD160","titel":"Ribbeck auswendig","text":"Lern die erste Strophe vom „Herrn von Ribbeck auf Ribbeck im Havelland“ auswendig. Morgen früh wird ohne Zettel aufgesagt.","min":10,"tf":"ABC","kat":"Lernen","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD161","titel":"Woher kommt das Wort?","text":"Schlag die Herkunft von „Kiez“, „Kneipe“ und „Schlamassel“ nach. Mindestens eins kommt von weiter her, als man denkt.","min":10,"tf":"ABC","kat":"Lernen","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD163","titel":"Latein für Zauberer","text":"Nimm drei Zaubersprüche aus Harry Potter, etwa „Lumos“, „Alohomora“ und „Expelliarmus“, und find ihre lateinischen Wurzeln. Danach verstehst du die Zauberer besser als sie sich selbst.","min":10,"tf":"ABC","kat":"Lernen","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD164","titel":"Bruegels Sprichwörter","text":"Ruf Bruegels „Niederländische Sprichwörter“ auf, das Original hängt in der Berliner Gemäldegalerie, und find zehn Redensarten im Bild.","min":15,"tf":"ABC","kat":"Lernen","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD168","titel":"Drei Bäume, drei Belege","text":"Find heraus, welche drei Baumarten im Spandauer Forst am häufigsten stehen, und such beim nächsten Gang je ein Exemplar.","min":10,"tf":"ABC","kat":"Lernen","haltung":"im Sitzen, im Liegen","t":"gelernt"},

  /* ---------- Erinnern ---------- */
  {"id":"SD146","titel":"Sätze, die blieben","text":"Schreib drei Sätze auf, die dir mal jemand gesagt hat und die du nie vergessen hast, mit Absender und Jahr.","min":10,"tf":"ABC","kat":"Erinnern","haltung":"im Sitzen, im Liegen","t":"erinnern"},
  {"id":"SD148","titel":"Laufschuhe, hochgerechnet","text":"Zähl die Paar Laufschuhe auf, die du in deinem Leben durchgelaufen hast, und rechne die Kilometer hoch. Einmal um die Erde?","min":10,"tf":"ABC","kat":"Erinnern","haltung":"im Sitzen, im Liegen","t":"erinnern"},
  {"id":"SD149","titel":"Antwort an früher","text":"Schlag ein altes Tagebuch an einer beliebigen Stelle auf und schreib deinem damaligen Ich einen Satz zurück.","min":10,"tf":"ABC","kat":"Erinnern","haltung":"im Sitzen","t":"tagebuch"},

  /* ---------- Listen ---------- */
  {"id":"SD241","titel":"Was ich am Handy noch können will","text":"Schreib eine Liste mit allem, was dein Handy kann und du noch nicht. Jede Woche wird ein Punkt abgehakt – und Max bekommt die Liste als Auftrag.","min":10,"tf":"ABC","kat":"Listen","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD151","titel":"Das Forst-Alphabet","text":"Schreib ein Alphabet des Spandauer Forsts: A wie Ahorn, B wie Buntspecht … Für Q und X gibt es Sonderpunkte.","min":15,"tf":"ABC","kat":"Listen","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD152","titel":"Fünf Lieblingswörter","text":"Notier deine fünf deutschen Lieblingswörter und begründe jedes mit einem halben Satz. „Kladderadatsch“ ist schon vergeben.","min":10,"tf":"ABC","kat":"Listen","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD153","titel":"Kaffee mit Zauberern","text":"Mach eine Rangliste: die fünf Figuren aus den ersten drei Bänden, mit denen du am liebsten Kaffee trinken würdest, und die eine, mit der auf keinen Fall. Nach dem „Feuerkelch“ wird neu gewählt.","min":10,"tf":"ABC","kat":"Listen","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD155","titel":"Der gereimte Einkaufszettel","text":"Schreib den nächsten Einkaufszettel so, dass er sich reimt. „Butter“ auf „Futter“ ist erlaubt, aber nur einmal.","min":10,"tf":"ABC","kat":"Listen","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD156","titel":"Unnütze Fähigkeiten","text":"Schreib alles auf, was du kannst und kein Mensch braucht: Kirschkernweitspucken, Fahrpläne auswendig, Ohrenwackeln.","min":10,"tf":"ABC","kat":"Listen","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD158","titel":"Sechs Gäste, eine Tafel","text":"Lad im Kopf sechs Gäste zum Abendessen ein, lebend oder historisch, und mach eine Sitzordnung. Wer muss neben Fontane sitzen?","min":10,"tf":"ABC","kat":"Listen","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD159","titel":"Berlinisch für Bayern","text":"Schreib zehn Berliner Ausdrücke auf und übersetz sie für jemanden aus München. „Nu mach ma’ halblang“ zählt doppelt.","min":10,"tf":"ABC","kat":"Listen","haltung":"im Sitzen, im Liegen","t":"tagebuch"},

  /* ---------- Kontakt ---------- */
  {"id":"SD169","titel":"Eine Karte mit Lücke","text":"Schreib Christiane eine Karte, in der ein Wort fehlt, das sie erraten muss. Die Auflösung gibt es erst am Telefon.","min":10,"tf":"ABC","kat":"Kontakt","haltung":"im Sitzen","t":"brief"},
  {"id":"SD170","titel":"Drei ungewöhnliche Fragen","text":"Schick Max drei Fragen, die ihm noch nie jemand gestellt hat, etwa: Welches Geräusch magst du am liebsten?","min":5,"tf":"ABC","kat":"Kontakt","haltung":"im Sitzen, im Liegen","t":"telefon"},
  {"id":"SD171","titel":"Kompliment mit Beleg","text":"Mach jemandem im Haus ein Kompliment, das so konkret ist, dass es unmöglich ausgedacht sein kann.","min":5,"tf":"ABC","kat":"Kontakt","haltung":"im Sitzen, im Stehen","t":"nachbar"},
  {"id":"SD172","titel":"Summ mal","text":"Summ eine Melodie als Sprachnachricht und lass raten, welches Lied das ist. Drei Versuche, dann wird aufgelöst.","min":3,"tf":"ABC","kat":"Kontakt","haltung":"im Sitzen, im Liegen","t":"telefon"},
  {"id":"SD173","titel":"Ein Buch in einem Satz","text":"Empfiehl jemandem ein Buch in genau einem Satz, ohne den Inhalt zu verraten. Du darfst ihn dreimal umschreiben, bevor er rausgeht.","min":5,"tf":"ABC","kat":"Kontakt","haltung":"im Sitzen, im Liegen","t":"brief"},
  {"id":"SD174","titel":"Ein Ausschnitt per Post","text":"Schneid einen Zeitungsartikel aus, der genau zu jemandem passt, und schick ihn mit einem einzigen Satz dazu.","min":10,"tf":"ABC","kat":"Kontakt","haltung":"im Sitzen","t":"brief"},

  /* ---------- Hände ---------- */
  {"id":"SD178","titel":"Stillleben mit Löffel","text":"Stell drei Dinge vom Küchentisch zusammen und zeichne sie in zehn Minuten. Der Löffel ist der schwerste.","min":10,"tf":"ABC","kat":"Hände","haltung":"im Sitzen","t":"handarbeit"},
  {"id":"SD179","titel":"Was ist das?","text":"Fotografier etwas in der Wohnung so nah, dass es niemand erkennt, und schick es Max zum Raten.","min":5,"tf":"ABC","kat":"Hände","haltung":"im Sitzen, im Stehen","t":"foto"},
  {"id":"SD180","titel":"Buchführung auf dem Balkon","text":"Zähl auf dem Balkon Knospen, neue Triebe und welke Blätter und trag alles in eine kleine Tabelle ein. In einer Woche wird verglichen.","min":10,"tf":"ABC","kat":"Hände","haltung":"im Sitzen, im Stehen","t":"pflanzen"},

  /* ---------- Ordnen ---------- */
  {"id":"SD181","titel":"Ein Jahrgang Fotos","text":"Such alle Fotos eines einzigen Jahres zusammen und bring sie in die richtige Reihenfolge. Die Datierung ist das eigentliche Rätsel.","min":20,"tf":"AB","kat":"Ordnen","haltung":"im Sitzen","t":"ordnung"},
  {"id":"SD182","titel":"Gewürze von Anis bis Zimt","text":"Sortier das Gewürzregal nach dem Alphabet. Die Dose mit dem ältesten Datum bekommt eine Ehrenurkunde.","min":15,"tf":"AB","kat":"Ordnen","haltung":"im Sitzen, im Stehen","t":"ordnung"},

  /* ======== Erweiterung: mehr Futter ======== */

  /* ---------- Krimi ---------- */
  {"id":"SD242","titel":"Wallanders Wohnung finden","text":"Kommissar Wallander wohnt in Ystad in der Mariagatan. Such die Straße in Google Maps, geh mit Street View davor auf und ab und entscheide, welches Fenster seins ist.","min":15,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen","t":"gelernt",
    "schritte":["Google Maps öffnen und „Mariagatan, Ystad“ suchen.","Lange auf die Straße drücken, bis eine Markierung erscheint. Unten zeigt sich ein kleines Foto – antippen, dann bist du in Street View.","Mit dem Finger wischen, um dich umzusehen, und auf die Pfeile tippen, um weiterzugehen.","Zum Abschluss: Wie weit ist es von dort zum Hafen? Schätzen, dann nachsehen."]},
  {"id":"SD243","titel":"Wer ist Lars Kepler?","text":"Hinter dem Krimi-Autor Lars Kepler („Der Hypnotiseur“) steckt ein Geheimnis, das jahrelang gut gehütet wurde. Find es heraus und erzähl es beim nächsten Telefonat.","min":10,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD244","titel":"Martin Beck, alle zehn","text":"Maj Sjöwall und Per Wahlöö schrieben zwischen 1965 und 1975 genau zehn Martin-Beck-Krimis, die Urahnen aller Schwedenkrimis. Schreib die Reihenfolge ins Tagebuch und hak ab, welche du schon kennst.","min":10,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD245","titel":"Der Titel auf Schwedisch","text":"Stieg Larssons „Verblendung“ heißt im Original „Män som hatar kvinnor“. Übersetz den Originaltitel und such zwei weitere Schwedenkrimis, deren deutscher Titel ganz anders klingt.","min":10,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD246","titel":"Mord im Juliusturm","text":"Schreib einen Spandau-Krimi in genau fünf Sätzen: Tatort, Leiche, Ermittlerin, falsche Fährte, Täter. Schwedisch düster oder Berliner Schnauze – du entscheidest.","min":15,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD247","titel":"Indizien auf Seite eins","text":"Lies die erste Seite eines neuen Krimis und notier drei Dinge, die dir verdächtig vorkommen. Am Ende wird geprüft, ob du einer echten Spur auf der Spur warst.","min":10,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen, im Liegen","t":"lesen"},
  {"id":"SD248","titel":"Steckbrief für eine Kommissarin","text":"Schreib einen Steckbrief deiner liebsten Ermittlerfigur: Wohnort, Auto, Lieblingsessen, schlechte Angewohnheit, bester Satz. Wallander, Annika Bengtzon oder Rebecka Martinsson?","min":10,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD249","titel":"Fjällbacka und der Filmstar","text":"In Fjällbacka spielen Camilla Läckbergs Krimis, und auf dem Marktplatz erinnert ein Platz an einen Weltstar, der dort die Sommer verbrachte. Find heraus, wer das war.","min":10,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD250","titel":"Der Meisterdetektiv aus Vimmerby","text":"Astrid Lindgren aus Vimmerby hat nicht nur Pippi erfunden, sondern auch einen jungen Meisterdetektiv. Find heraus, wie er heißt, Kleiner Tipp: Karin aus „Post aus Vimmerby“ hat ihn als Kind verschlungen.","min":10,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen, im Liegen","t":"brief"},
  {"id":"SD251","titel":"Krimis ausleihen, ohne rauszugehen","text":"Mit einem Ausweis der Berliner Bibliotheken (VÖBB) kannst du E-Books und Hörbücher aufs Handy ausleihen, auch Schwedenkrimis. Der Ausweis lässt sich online anlegen, Ausleihen kostet höchstens 10 € im Jahr.","min":20,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen","t":"erstesmal",
    "schritte":["Auf voebb.de „Jetzt Ausweis erstellen!“ suchen und das Formular ausfüllen. Oder den Ausweis beim nächsten Gang in der Stadtbibliothek Spandau holen.","Unter „Digitale Angebote“ nachsehen, welche Ausleih-Plattform für E-Books und Hörbücher die richtige ist.","Die passende App aus dem Play Store installieren und mit Ausweisnummer und Passwort anmelden.","Nach „Mankell“, „Nesser“ oder „Läckberg“ suchen und den ersten Krimi ausleihen."],
    "links":[{"text":"VÖBB – Digitale Angebote","url":"https://www.voebb.de/digitale-angebote"}]},
  {"id":"SD252","titel":"Der Krimi-Atlas","text":"Trag auf einer Schwedenkarte ein, wo deine Krimis spielen: Ystad (Mankell), Fjällbacka (Läckberg), Kiruna (Åsa Larsson), Sandhamn (Viveca Sten), Öland (Johan Theorin). Wo ist es am gefährlichsten?","min":15,"tf":"ABC","kat":"Krimi","haltung":"im Sitzen","t":"gelernt"},

  /* ---------- Schwedisch ---------- */
  {"id":"SD253","titel":"Ein Wettersatz auf Schwedisch","text":"Bau einen Satz über das Wetter in Spandau auf Schwedisch, zum Beispiel „Idag regnar det i Spandau, men jag har te.“ Schreib ihn auf eine Karte nach Schweden oder sag ihn beim nächsten Telefonat einfach mal auf.","min":5,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen, im Liegen","t":"brief"},
  {"id":"SD254","titel":"Die Küche auf Schwedisch","text":"Kleb Zettel mit den schwedischen Namen an zehn Dinge in der Küche. Eine Woche hängen lassen, dann ohne Zettel abfragen.","min":15,"tf":"ABC","kat":"Schwedisch","haltung":"im Stehen","t":"gelernt",
    "optionen":["kylskåp – Kühlschrank","spis – Herd","kaffebryggare – Kaffeemaschine","diskbänk – Spüle","kopp – Tasse","tallrik – Teller","sked – Löffel","gaffel – Gabel","kniv – Messer","brödrost – Toaster"]},
  {"id":"SD255","titel":"Falsche Freunde","text":"Manche schwedischen Wörter klingen deutsch und meinen etwas ganz anderes. Lern die fünf gefährlichsten, bevor dir in Schweden etwas Peinliches rausrutscht. Karin aus „Post aus Vimmerby“ kennt ein paar davon.","min":10,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen, im Liegen","t":"gelernt",
    "optionen":["rolig – lustig (nicht ruhig)","glass – Speiseeis","semester – Urlaub","fart – Geschwindigkeit","slut – Ende, Schluss","kissa – pinkeln (nicht küssen!)"]},
  {"id":"SD256","titel":"Keine Kuh auf dem Eis","text":"Die Schweden sagen „Det är ingen ko på isen“, wenn es keinen Grund zur Sorge gibt. Such dir eine schwedische Redensart aus und bring sie Max bei – per Nachricht, als Sprachnachricht oder beim nächsten Telefonat. Wer’s versteht, lacht.","min":10,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen, im Liegen","t":"gelernt","rede":true},
  {"id":"SD257","titel":"Fika mit Bericht","text":"Fika ist die schwedische Kaffeepause mit etwas Süßem, am besten einer Zimtschnecke. Mach heute eine richtige Fika und sag auf Schwedisch, was es gab: „Jag fikar med …“. Karin in Vimmerby wäre stolz.","min":20,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen","t":"goennen",
    "optionen":["kanelbulle – Zimtschnecke","kaffe med mjölk – Kaffee mit Milch","Det var gott! – Das war lecker!","Den 4 oktober är det kanelbullens dag – am 4. Oktober ist Zimtschnecken-Tag"]},
  {"id":"SD258","titel":"Pippis ganzer Name","text":"Pippi Langstrumpf heißt mit vollem Namen Pippilotta Viktualia Rullgardina Krusmynta Efraimsdotter Långstrump. Find heraus, was die einzelnen Teile bedeuten – „Rullgardina“ ist der beste.","min":10,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD259","titel":"IKEA-Namen entschlüsseln","text":"Bei IKEA heißen die Möbel nach einem System, und die Namen sind echte schwedische Wörter, Orte und Vornamen. Find heraus, was deine eigenen IKEA-Sachen auf Deutsch bedeuten.","min":10,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen","t":"gelernt"},
  {"id":"SD260","titel":"Zahlen bis zwanzig, laut","text":"Zähl auf Schwedisch bis zwanzig, laut, und sag danach deine Telefonnummer auf Schwedisch. „Sju“ und „tjugo“ sind die Feinschmecker-Zahlen.","min":5,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD261","titel":"Nachrichten auf leichtem Schwedisch","text":"Die schwedischen Sender machen Nachrichten in einfachem Schwedisch für alle, die die Sprache lernen. Such im Netz nach „nyheter på lätt svenska“ und versuch, eine Meldung zu verstehen.","min":10,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen, im Liegen","t":"gelernt",
    "hoeren":[{"text": "Nachrichten auf leichtem Schwedisch (YouTube)", "url": "https://www.youtube.com/results?search_query=nyheter+p%C3%A5+l%C3%A4tt+svenska", "spotify": "Radio Sweden på lätt svenska"}]},
  {"id":"SD262","titel":"Eine Frage auf Schwedisch","text":"Lern drei Fragen, die ein Gespräch in Gang bringen, etwa „Vad läser du just nu?“ – Was liest du gerade? In Karins nächstem Brief aus Vimmerby kannst du schauen, ob du sie wiedererkennst.","min":10,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen, im Liegen","t":"brief"},
  {"id":"SD263","titel":"Ein schwedisches Lied verstehen","text":"Hör „Vem kan segla förutan vind?“, eines der bekanntesten Volkslieder auf Schwedisch, und übersetz die erste Strophe. Es sind nur vier Zeilen, aber was für welche.","min":15,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen, im Liegen","t":"musik",
    "gedicht":{"titel": "Vem kan segla förutan vind?", "autor": "Volkslied, vermutlich von den Åland-Inseln", "original": "Vem kan segla förutan vind?\nVem kan ro utan åror?\nVem kan skiljas från vännen sin\nutan att fälla tårar?\n\nJag kan segla förutan vind,\njag kan ro utan åror,\nmen ej skiljas från vännen min\nutan att fälla tårar.", "deutsch": "Wer kann segeln ohne Wind?\nWer kann rudern ohne Ruder?\nWer kann scheiden vom Freunde sein,\nohne Tränen zu vergießen?\n\nIch kann segeln ohne Wind,\nich kann rudern ohne Ruder,\ndoch nicht scheiden vom Freunde mein,\nohne Tränen zu vergießen.", "hinweis": "Ein altes Volkslied, in dieser Form 1909 zuerst gedruckt; die zweite Strophe ist die Antwort auf die erste."},
    "hoeren":[{"text": "Auf YouTube anhören", "url": "https://www.youtube.com/results?search_query=Vem+kan+segla+f%C3%B6rutan+vind", "spotify": "Vem kan segla förutan vind"}]},
  {"id":"SD264","titel":"Allemansrätten erklären","text":"In Schweden darf jeder fast überall durch die Natur laufen und sogar eine Nacht zelten: das Jedermannsrecht. Find die drei wichtigsten Regeln heraus und vergleich sie mit dem Spandauer Forst.","min":10,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD265","titel":"Das Dala-Pferd","text":"Das rote Holzpferdchen aus Dalarna ist Schwedens bekanntestes Andenken. Find heraus, wer es ursprünglich geschnitzt hat, und zeichne eins mit den typischen Blumen.","min":15,"tf":"ABC","kat":"Schwedisch","haltung":"im Sitzen","t":"handarbeit"},

  /* ---------- Handy, Teil 2 ---------- */
  {"id":"SD266","titel":"Bildschirmfoto machen","text":"Ein Bildschirmfoto ist der schnellste Hilferuf an Max: Er sieht genau, was du siehst. Zwei Tasten gleichzeitig, und es ist im Kasten.","min":5,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"erstesmal",
    "schritte":["Ein-/Aus-Taste und Leiser-Taste gleichzeitig kurz drücken.","Es blitzt kurz, unten erscheint ein kleines Vorschaubild.","Das Bild liegt danach in deinen Fotos im Ordner „Screenshots“.","Übung: Schick Max ein Bildschirmfoto von dieser Idee."]},
  {"id":"SD267","titel":"Welches Lied ist das? Summ es!","text":"Du hast eine Melodie im Kopf und weißt den Titel nicht? Summ sie dem Handy vor, und Google findet das Lied. Klingt unglaublich, klappt aber.","min":5,"tf":"ABC","kat":"Handy","haltung":"im Sitzen, im Liegen","t":"erstesmal",
    "schritte":["Die Google-App öffnen oder in der Google-Suchleiste auf das Mikrofon tippen.","Auf „Song suchen“ tippen.","10 bis 15 Sekunden summen, pfeifen oder singen. Erster Versuch daneben? Ein zweites Mal mit dem Refrain klappt oft.","Google zeigt die wahrscheinlichsten Lieder. Läuft im Radio etwas Unbekanntes, geht es genauso, oder mit der App Shazam."],
    "links":[{"text":"Shazam im Play Store","url":"https://play.google.com/store/apps/details?id=com.shazam.android"}]},
  {"id":"SD268","titel":"Wer singt da im Forst?","text":"Die kostenlose App BirdNET hört zu und sagt dir, welcher Vogel gerade singt. Drei neue Arten beim nächsten Gang, und du bist die Vogelkundlerin im Haus.","min":15,"tf":"AB","kat":"Handy","haltung":"unterwegs","t":"natur",
    "schritte":["BirdNET aus dem Play Store installieren und das Mikrofon erlauben.","Draußen auf den Aufnahme-Knopf tippen, wenn ein Vogel singt.","Die App zeigt die Art mit Bild und wie sicher sie ist.","Neue Arten ins Tagebuch – im Herbst sind es weniger Sänger, umso stolzer der Fund."],
    "links":[{"text":"BirdNET im Play Store","url":"https://play.google.com/store/apps/details?id=de.tu_chemnitz.mi.kahst.birdnet"}]},
  {"id":"SD269","titel":"Das Handy als Lupe","text":"Kleingedrucktes auf Packungen und Fahrplänen? Die Kamera vergrößert es dir. Das spart die Suche nach der Lesebrille.","min":5,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"erstesmal",
    "schritte":["Die Kamera-App öffnen.","Mit zwei Fingern auf dem Bildschirm auseinanderziehen – das Bild wird größer.","Wenn es ruckelt: einfach ein Foto machen und das Foto vergrößern.","Bei vielen Handys gibt es auch eine eigene „Lupe“: in den Einstellungen danach suchen."]},
  {"id":"SD270","titel":"Text abfotografieren und verschicken","text":"Google Lens kann Text auf einem Foto erkennen, und du kannst ihn kopieren und verschicken. Zum Beispiel ein Rezept aus der Zeitung an Max.","min":10,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"erstesmal",
    "schritte":["Google Lens öffnen.","Die Kamera auf den Zeitungsartikel halten und auslösen.","Auf „Text auswählen“ tippen (oder den Text direkt mit dem Finger markieren) und „Kopieren“ wählen.","In einer Nachricht an Max lange in das Textfeld tippen und „Einfügen“ wählen."],
    "links":[{"text":"Google Lens im Play Store","url":"https://play.google.com/store/apps/details?id=com.google.ar.lens"}]},
  {"id":"SD271","titel":"Panorama vom Forstrand","text":"Fotografier einmal einen ganzen Halbkreis auf einem Bild, mit der Panorama-Funktion. Das Ergebnis bekommt Max als Beweis, wie schön es bei dir ist.","min":10,"tf":"AB","kat":"Handy","haltung":"im Stehen, unterwegs","t":"foto",
    "schritte":["Kamera öffnen und bei den Modi (oft unter „Mehr“) „Panorama“ wählen.","Auslöser tippen und das Handy langsam und gleichmäßig zur Seite schwenken.","Dem Pfeil auf dem Bildschirm folgen, am Ende noch einmal tippen.","Ergebnis anschauen – schiefe Horizonte gelten als Kunst."]},
  {"id":"SD272","titel":"Eine Liste in Google Maps","text":"Du liebst Listen? Google Maps auch. Leg eine Liste „Ausflüge“ an und speichere fünf Ziele, die du dieses Jahr noch ansteuern willst.","min":10,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"gelernt",
    "schritte":["Google Maps öffnen und ein Ziel suchen, etwa „Zitadelle Spandau“.","Auf „Speichern“ tippen und „Neue Liste“ wählen, Name: „Ausflüge“.","Vier weitere Ziele suchen und in dieselbe Liste speichern.","Die Liste findest du unten unter „Gespeichert“ – und sie lässt sich mit Max teilen."]},
  {"id":"SD273","titel":"Wie lang ist meine Runde?","text":"Google Maps misst dir jede Strecke aus, Punkt für Punkt. Find heraus, wie viele Meter deine Lieblingsrunde wirklich hat.","min":10,"tf":"ABC","kat":"Handy","haltung":"im Sitzen","t":"gelernt",
    "schritte":["Google Maps öffnen und zum Startpunkt deiner Runde schieben.","Lange auf den Startpunkt drücken, bis eine rote Markierung erscheint.","Unten das Infofeld hochwischen und „Entfernung messen“ wählen.","Die Karte verschieben und mit „+“ weitere Punkte setzen. Unten steht die Länge."]},
  {"id":"SD274","titel":"Videoanruf mit Balkon-Rundgang","text":"Ruf Max per Video an und zeig ihm live deinen Balkon, deine Pflanzen und den Forst. Er ist Kameramann aus der Ferne und darf Regie führen.","min":15,"tf":"ABC","kat":"Handy","haltung":"im Sitzen, im Stehen","t":"telefon",
    "schritte":["Den Chat mit Max öffnen (zum Beispiel WhatsApp).","Oben auf das Kamera-Symbol tippen.","Mit dem Pfeil-Symbol zwischen Vorder- und Rückkamera wechseln.","Rundgang machen und Max raten lassen, was neu ist."]},

  /* ---------- Geschichte, Teil 2 ---------- */
  {"id":"SD275","titel":"Die vier Bastionen der Zitadelle","text":"Die Zitadelle Spandau ist eine der besterhaltenen Festungen der Renaissance in Europa. Find heraus, wie ihre vier Bastionen heißen – sie haben sehr königliche Namen.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD276","titel":"Als die Schweden die Zitadelle wollten","text":"1631 zwang der Schwedenkönig Gustav II. Adolf den brandenburgischen Kurfürsten, ihm die Zitadelle Spandau zu überlassen. Find heraus, wie lange die Schweden blieben – eine schöne Anekdote fürs nächste Telefonat.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD277","titel":"Rosinenbomber über Gatow","text":"Während der Luftbrücke 1948/49 landeten auch auf dem Flugplatz Gatow, gleich in Spandau, die Versorgungsflugzeuge. Find heraus, was dort heute zu sehen ist, und merk es dir als Ausflugsziel.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD278","titel":"Die Quadriga auf Reisen","text":"Napoleon ließ 1806 die Quadriga vom Brandenburger Tor nach Paris bringen, 1814 kam sie zurück. Angeblich stammt daher das Wort „Retourkutsche“ – find heraus, ob das stimmt.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD279","titel":"Osmium plus Wolfram","text":"Der Name Osram ist 1906 in Berlin entstanden und steckt voller Chemie. Find heraus, aus welchen zwei Wörtern er gebaut ist, und denk dir eine eigene Firma nach dem gleichen Prinzip aus.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD280","titel":"Der Mann hinter dem Ampelmännchen","text":"Das Ost-Ampelmännchen mit Hut wurde 1961 von einem Verkehrspsychologen erfunden und hat die Wende überlebt. Find seinen Namen heraus und warum das Männchen so pummelig ist.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD281","titel":"Fontane war schon da","text":"Theodor Fontane hat in seinen „Wanderungen durch die Mark Brandenburg“ auch über Spandau geschrieben. Lies das Kapitel im Netz und finde einen Satz, der heute noch stimmt.","min":20,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"lesen"},
  {"id":"SD282","titel":"Der Kartoffeltrick des Königs","text":"Friedrich der Große soll Kartoffelfelder bewachen lassen haben, damit die Bauern sie für wertvoll hielten und klauten. Find heraus, ob das Legende ist, und wo heute Kartoffeln auf seinem Grab liegen.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD283","titel":"Reformation in Spandau","text":"Am 1. November 1539 nahm Kurfürst Joachim II. in der Spandauer Nikolaikirche das Abendmahl nach evangelischer Art – der Beginn der Reformation in Brandenburg. Find heraus, wessen Denkmal heute vor der Kirche steht.","min":10,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD284","titel":"Herr Litfaß und seine Säule","text":"1855 stellte der Drucker Ernst Litfaß in Berlin die ersten Anschlagsäulen auf, damit die Leute nicht mehr wild plakatierten. Zähl beim nächsten Gang, wie viele Litfaßsäulen du findest.","min":5,"tf":"ABC","kat":"Geschichte","haltung":"im Sitzen, unterwegs","t":"gelernt"},

  /* ---------- Essen, Teil 2 ---------- */
  {"id":"SD285","titel":"Haferflocken über Nacht","text":"Abends zwei Minuten Arbeit, morgens ein fertiges Frühstück mit gut 20 g Eiweiß. Overnight Oats heißt das neudeutsch, Rita-Müsli reicht auch.","min":5,"tf":"ABC","kat":"Essen","haltung":"im Stehen","t":"kochen",
    "schritte":["40 g Haferflocken, 150 g Skyr und 100 ml Milch in ein Glas mit Deckel geben.","Umrühren, eine Prise Zimt dazu.","Über Nacht in den Kühlschrank.","Morgens Obst darauf, zum Beispiel einen geriebenen Apfel oder Beeren."]},
  {"id":"SD286","titel":"Rührei mit Bonus","text":"Zwei Eier plus zwei Löffel Hüttenkäse ergeben ein besonders cremiges Rührei mit rund 20 g Eiweiß. Der Trick kommt aus der Sportlerküche und schmeckt trotzdem.","min":10,"tf":"ABC","kat":"Essen","haltung":"im Stehen","t":"kochen",
    "schritte":["2 Eier mit 2 EL Hüttenkäse, Salz und Pfeffer verquirlen.","In etwas Butter bei mittlerer Hitze langsam stocken lassen.","Schnittlauch darüber.","Dazu ein Vollkornbrot."]},
  {"id":"SD287","titel":"Knusper-Kichererbsen","text":"Aus einer Dose Kichererbsen wird im Ofen ein knuspriger Knabberspaß, der Chips Konkurrenz macht. Mit Eiweiß und ohne Reue.","min":35,"tf":"ABC","kat":"Essen","haltung":"im Stehen","t":"kochen",
    "schritte":["Ofen auf 200 °C vorheizen.","Eine Dose Kichererbsen abgießen, abspülen und mit einem Küchentuch gut trocken tupfen.","Mit 1 EL Öl, Paprikapulver und Salz mischen, auf ein Blech mit Backpapier.","25 bis 30 Minuten rösten, einmal wenden. Abkühlen lassen – dann werden sie richtig knusprig."]},
  {"id":"SD288","titel":"Der Fisch-Vorrat für faule Tage","text":"Hering in Tomatensoße, Thunfisch, Lachs oder Makrele aus der Dose sind fertige Eiweißportionen, die monatelang halten. Leg dir drei Sorten in den Schrank und probier eine neue aus.","min":10,"tf":"ABC","kat":"Essen","haltung":"im Sitzen, im Stehen","t":"kochen"},
  {"id":"SD289","titel":"Wasser mit Geschmack","text":"Etwa 1,5 Liter am Tag empfiehlt die Deutsche Gesellschaft für Ernährung, und mit Geschmack geht das leichter. Mach dir eine Karaffe mit Gurke, Zitrone oder Minze und guck, ob sie bis abends leer ist.","min":5,"tf":"ABC","kat":"Essen","haltung":"im Stehen","t":"getrunken"},
  {"id":"SD290","titel":"Quark gegen Skyr gegen Joghurt","text":"Probier Magerquark, Skyr und Naturjoghurt nebeneinander und vergleich danach auf der Packung den Eiweißgehalt. Der Gewinner kommt in den Einkaufszettel.","min":10,"tf":"ABC","kat":"Essen","haltung":"im Sitzen","t":"gelernt"},
  {"id":"SD291","titel":"Die Brotbelag-Rangliste","text":"Welcher Belag bringt am meisten Eiweiß aufs Brot: Harzer, Gouda, Frischkäse, Schinken oder Hüttenkäse? Erst raten, dann auf den Packungen nachsehen. Der Harzer überrascht.","min":10,"tf":"ABC","kat":"Essen","haltung":"im Sitzen, im Stehen","t":"gelernt"},

  /* ---------- Körper, Teil 2 ---------- */
  {"id":"SD292","titel":"Brücke im Bett","text":"Rückenlage, Füße aufgestellt, Becken anheben: Das stärkt Po und Rücken und geht sogar morgens vor dem Aufstehen. Zehnmal, dann darfst du in den Tag.","min":5,"tf":"ABCD","kat":"Körper","haltung":"im Liegen","t":"gymnastik",
    "schritte":["Auf dem Rücken liegen, Knie anwinkeln, Füße hüftbreit aufstellen.","Ausatmen und das Becken langsam anheben, bis Knie, Hüfte und Schultern eine Linie bilden.","Zwei Sekunden halten, langsam absenken.","10-mal. Wenn’s im Rücken zieht: kleiner werden."]},
  {"id":"SD293","titel":"Der Tennisball-Händedruck","text":"Ein kräftiger Händedruck öffnet Gläser und Türen. Knete einen Tennisball oder ein Paar zusammengerollte Socken, während das Radio läuft.","min":5,"tf":"ABCD","kat":"Körper","haltung":"im Sitzen, im Liegen","t":"gymnastik",
    "schritte":["Ball in eine Hand nehmen und fest zusammendrücken.","Drei Sekunden halten, loslassen.","10-mal pro Hand, zwei Runden.","Test: Geht das Gurkenglas danach leichter auf?"]},
  {"id":"SD296","titel":"Liegestütz an der Wand","text":"Liegestütze gehen auch im Stehen, gegen die Wand. Sie stärken Arme und Brust, und niemand muss auf den Boden.","min":5,"tf":"AB","kat":"Körper","haltung":"im Stehen","t":"gymnastik",
    "schritte":["Eine Armlänge vor die Wand stellen, Hände auf Schulterhöhe an die Wand.","Langsam die Arme beugen, bis die Nase fast die Wand berührt.","Wieder wegdrücken, der Körper bleibt gerade.","10-mal, zwei Runden. Weiter weg stehen macht es schwerer."]},
  {"id":"SD297","titel":"Treppen zählen","text":"Zähl die Stufen in deinem Haus und rechne aus, wie viele Höhenmeter du am Tag schaffst. Eine Woche lang, und du weißt, ob du schon auf den Teufelsberg gestiegen bist.","min":5,"tf":"AB","kat":"Körper","haltung":"im Stehen","t":"alltag"},
  {"id":"SD298","titel":"Bauch im Sitzen","text":"Auch die Bauchmuskeln lassen sich im Sitzen trainieren: Knie anheben und halten. Sie stützen den Rücken, der freut sich.","min":5,"tf":"ABCD","kat":"Körper","haltung":"im Sitzen","t":"gymnastik",
    "schritte":["Aufrecht auf die vordere Stuhlhälfte setzen, Hände seitlich an der Sitzfläche.","Ein Knie einige Zentimeter anheben, Bauch fest, drei Sekunden halten.","Absetzen, anderes Bein.","10-mal pro Seite."]},
  {"id":"SD299","titel":"Schultern frei","text":"Wer viel liest und aufs Handy schaut, schiebt die Schultern nach vorn. Zieh sie zurück: Schulterblätter zusammen, halten, loslassen.","min":3,"tf":"ABCD","kat":"Körper","haltung":"im Sitzen, im Stehen","t":"dehnen",
    "schritte":["Aufrecht sitzen, Arme locker hängen.","Schultern hochziehen, nach hinten rollen und die Schulterblätter zusammenziehen.","Drei Sekunden halten, loslassen.","10-mal. Gut nach jedem Kapitel."]},

  /* ---------- Lesen, Hören, Musik, Sinne – Teil 2 ---------- */
  {"id":"SD301","titel":"Zufallsartikel","text":"Wikipedia hat einen Knopf für einen zufälligen Artikel. Lies drei, und erzähl den merkwürdigsten heute noch jemandem.","min":15,"tf":"ABCD","kat":"Lesen","haltung":"im Sitzen, im Liegen","t":"gelernt",
    "schritte":["de.wikipedia.org im Browser öffnen.","Oben links das Menü (drei Striche) antippen und „Zufällig“ bzw. „Zufälliger Artikel“ wählen.","Dreimal wiederholen und den merkwürdigsten Artikel ins Tagebuch schreiben."]},
  {"id":"SD302","titel":"Die Zeitung in drei Sätzen","text":"Such dir den längsten Artikel der heutigen Zeitung und fass ihn in drei Sätzen für Max zusammen. Kürzen ist die hohe Kunst.","min":15,"tf":"ABCD","kat":"Lesen","haltung":"im Sitzen","t":"lesen"},
  {"id":"SD303","titel":"Wallander zum Hören","text":"Hör die ersten zwei Kapitel von Henning Mankells „Mörder ohne Gesicht“, dem ersten Wallander. Nach zwei Kapiteln: Hast du schon einen Verdacht?","min":30,"tf":"ABCD","kat":"Hören","haltung":"im Sitzen, im Liegen","t":"hoerbuch",
    "hoeren":[{"text": "Hörbuch ausleihen: VÖBB digital", "url": "https://www.voebb.de/digitale-angebote", "spotify": "Mankell Mörder ohne Gesicht"}, {"text": "Weitere Ermittlerkrimis in ARD Sounds", "url": "https://www.ardsounds.de/sendung/auf-der-spur-ard-ermittlerkrimis/urn:ard:show:1b3dd6076b453726/"}]},
  {"id":"SD304","titel":"Schwedisch im Ohr","text":"Hör fünf Minuten schwedisches Radio oder Nachrichten auf leichtem Schwedisch und schreib danach jedes Wort auf, das du verstanden hast. Nächste Woche wird die Liste länger.","min":10,"tf":"ABCD","kat":"Hören","haltung":"im Sitzen, im Liegen","t":"radio",
    "hoeren":[{"text": "Nachrichten auf leichtem Schwedisch (YouTube)", "url": "https://www.youtube.com/results?search_query=nyheter+p%C3%A5+l%C3%A4tt+svenska", "spotify": "Radio Sweden på lätt svenska"}]},
  {"id":"SD305","titel":"Waterloo auf Schwedisch","text":"ABBA hat „Waterloo“ auch auf Schwedisch aufgenommen. Hör beide Fassungen nacheinander und entscheide, welche besser ist.","min":8,"tf":"ABCD","kat":"Musik","haltung":"im Sitzen, im Liegen","t":"musik",
    "hoeren":[{"text": "Schwedische Fassung (YouTube)", "url": "https://www.youtube.com/results?search_query=ABBA+Waterloo+svenska", "spotify": "ABBA Waterloo Swedish Version"}, {"text": "Englische Fassung (YouTube)", "url": "https://www.youtube.com/results?search_query=ABBA+Waterloo+1974", "spotify": "ABBA Waterloo"}]},
  {"id":"SD306","titel":"Original oder Cover?","text":"Viele Welthits sind gar nicht vom bekanntesten Sänger. Rate erst, wer jeweils das Original gesungen hat, dann hör es dir an.","min":15,"tf":"ABCD","kat":"Musik","haltung":"im Sitzen, im Liegen","t":"musik",
    "optionen":["„I Will Always Love You“ – Whitney Houston oder Dolly Parton?","„Respect“ – Aretha Franklin oder Otis Redding?","„Hallelujah“ – Jeff Buckley oder Leonard Cohen?","„Hound Dog“ – Elvis oder Big Mama Thornton?"],
    "hoeren":[{"text": "„I Will Always Love You“ (YouTube)", "url": "https://www.youtube.com/results?search_query=I+Will+Always+Love+You+Dolly+Parton+Whitney+Houston", "spotify": "I Will Always Love You"}, {"text": "„Respect“ (YouTube)", "url": "https://www.youtube.com/results?search_query=Respect+Otis+Redding+Aretha+Franklin", "spotify": "Respect"}, {"text": "„Hallelujah“ (YouTube)", "url": "https://www.youtube.com/results?search_query=Hallelujah+Leonard+Cohen+Jeff+Buckley", "spotify": "Hallelujah"}, {"text": "„Hound Dog“ (YouTube)", "url": "https://www.youtube.com/results?search_query=Hound+Dog+Big+Mama+Thornton+Elvis", "spotify": "Hound Dog"}]},
  {"id":"SD307","titel":"Karneval der Tiere","text":"Hör den „Karneval der Tiere“ von Saint-Saëns, ohne auf die Satztitel zu schauen, und rate bei jedem Stück, welches Tier gemeint ist. Der Elefant ist leicht, die Schildkröte gemein.","min":25,"tf":"ABCD","kat":"Musik","haltung":"im Sitzen, im Liegen","t":"musik",
    "hoeren":[{"text": "Auf YouTube anhören", "url": "https://www.youtube.com/results?search_query=Saint-Sa%C3%ABns+Karneval+der+Tiere", "spotify": "Saint-Saëns Karneval der Tiere"}]},
  {"id":"SD308","titel":"Vivaldis Herbst mit Gebrauchsanweisung","text":"Zu jeder seiner „Vier Jahreszeiten“ hat Vivaldi ein Gedicht geschrieben, das genau sagt, was passiert. Lies das Gedicht zum „Herbst“ (steht unten, mit Übersetzung) und hör dann, wo die betrunkenen Bauern einschlafen.","min":15,"tf":"ABCD","kat":"Musik","haltung":"im Sitzen, im Liegen","t":"musik",
    "gedicht":{"titel": "Sonett zum „Herbst“ (L'Autunno)", "autor": "Antonio Vivaldi zugeschrieben, 1725", "original": "Celebra il Vilanel con balli e Canti\nDel felice raccolto il bel piacere\nE del liquor de Bacco accesi tanti\nFiniscono col Sonno il lor godere\n\nFà ch' ogn' uno tralasci e balli e canti\nL' aria che temperata dà piacere,\nE la Staggion ch' invita tanti e tanti\nD' un dolcissimo Sonno al bel godere.\n\nI cacciator alla nov' alba à caccia\nCon corni, Schioppi, e cani escono fuore\nFugge la belva, e Seguono la traccia;\n\nGià Sbigottita, e lassa al gran rumore\nDe' Schioppi e cani, ferita minaccia\nLanguida di fuggir, mà oppressa muore.", "deutsch": "Der Bauer feiert mit Tanz und Gesang\ndie Freude über die gute Ernte,\nund viele, vom Wein des Bacchus erhitzt,\nbeenden ihr Vergnügen mit Schlaf.\n\nDie milde Luft, die so wohltut,\nlässt alle Tanz und Gesang beenden,\nund die Jahreszeit lädt viele, viele ein,\neinen süßen Schlaf zu genießen.\n\nIm Morgengrauen ziehen die Jäger zur Jagd hinaus,\nmit Hörnern, Flinten und Hunden.\nDas Wild flieht, sie folgen seiner Spur.\n\nSchon verstört und erschöpft vom großen Lärm\nder Flinten und Hunde, versucht es verwundet,\nmatt noch zu fliehen, doch es stirbt, überwältigt.", "hinweis": "Das Sonett steht in der Erstausgabe von 1725 über den Noten und wird Vivaldi selbst zugeschrieben; die altertümliche Schreibweise ist original."},
    "hoeren":[{"text": "Auf YouTube anhören", "url": "https://www.youtube.com/results?search_query=Vivaldi+Vier+Jahreszeiten+Herbst+L%27autunno", "spotify": "Vivaldi Vier Jahreszeiten Herbst"}]},
  {"id": "SD501", "titel": "Vivaldis Winter – mit Gedicht", "text": "Im „Winter“ klappern die Zähne, man rutscht übers Eis, und am Ende sitzt man warm am Feuer. Lies erst das Gedicht, dann hör zu und such die Stelle, an der jemand hinfällt.", "min": 10, "tf": "ABCD", "kat": "Musik", "haltung": "im Sitzen, im Liegen", "t": "musik",
    "gedicht":{"titel": "Sonett zum „Winter“ (L'Inverno)", "autor": "Antonio Vivaldi zugeschrieben, 1725", "original": "Agghiacciato tremar trà nevi algenti\nAl Severo Spirar d' orrido Vento,\nCorrer battendo i piedi ogni momento;\nE pel Soverchio gel batter i denti;\n\nPassar al foco i dì quieti e contenti\nMentre la pioggia fuor bagna ben cento\nCaminar Sopra il giaccio, e à passo lento\nPer timor di cader girsene intenti;\n\nGir forte Sdruzziolar, cader à terra\nDi nuove ir Sopra 'l giaccio e correr forte\nSin ch' il giaccio si rompe, e si disserra;\n\nSentir uscir dalle ferrate porte\nSirocco, Borea, e tutti i Venti in guerra\nQuest' è 'l verno, mà tal, che gioja apporte.", "deutsch": "Zitternd vor Kälte im eisigen Schnee,\nim scharfen Hauch eines grimmigen Windes,\nlaufen und alle Augenblicke mit den Füßen stampfen,\nund vor lauter Frost mit den Zähnen klappern.\n\nRuhige, zufriedene Tage am Feuer verbringen,\nwährend draußen der Regen alle durchnässt.\nÜbers Eis gehen, mit langsamen Schritten,\nganz vorsichtig, aus Angst zu fallen.\n\nHeftig ausrutschen, zu Boden stürzen,\nwieder aufs Eis gehen und schnell laufen,\nbis das Eis bricht und aufreißt.\n\nHören, wie aus den eisernen Toren\nSchirokko, Nordwind und alle Winde zum Kampf hervorbrechen:\nDas ist der Winter – aber einer, der auch Freude bringt.", "hinweis": "Das Sonett steht in der Erstausgabe von 1725 über den Noten und wird Vivaldi selbst zugeschrieben; die altertümliche Schreibweise ist original."},
    "hoeren":[{"text": "Auf YouTube anhören", "url": "https://www.youtube.com/results?search_query=Vivaldi+Vier+Jahreszeiten+Winter+L%27inverno", "spotify": "Vivaldi Vier Jahreszeiten Winter"}]},
  {"id": "SD502", "titel": "Vivaldis Frühling – mit Gedicht", "text": "Der „Frühling“ ist das berühmteste Stück der „Vier Jahreszeiten“. Lies das Gedicht und hör dann genau hin: Wo bellt im langsamen Satz der Hund des schlafenden Hirten?", "min": 10, "tf": "ABCD", "kat": "Musik", "haltung": "im Sitzen, im Liegen", "t": "musik",
    "gedicht":{"titel": "Sonett zum „Frühling“ (La Primavera)", "autor": "Antonio Vivaldi zugeschrieben, 1725", "original": "Giunt' è la Primavera e festosetti\nLa Salutan gl' Augei con lieto canto,\nE i fonti allo Spirar de' Zeffiretti\nCon dolce mormorio Scorrono intanto:\n\nVengon' coprendo l' aer di nero amanto\nE Lampi, e tuoni ad annuntiarla eletti\nIndi tacendo questi, gl' Augelletti;\nTornan' di nuovo al lor canoro incanto:\n\nE quindi sul fiorito ameno prato\nAl caro mormorio di fronde e piante\nDorme 'l Caprar col fido can' à lato.\n\nDi pastoral Zampogna al suon festante\nDanzan Ninfe e Pastor nel tetto amato\nDi primavera all' apparir brillante.", "deutsch": "Der Frühling ist da, und fröhlich\nbegrüßen ihn die Vögel mit heiterem Gesang,\nund die Quellen fließen im Hauch der sanften Winde\nleise murmelnd dahin.\n\nDann ziehen Blitz und Donner auf,\ndie ihn ankündigen, und hüllen den Himmel in schwarzen Mantel.\nSind sie verstummt, kehren die Vögelchen\nzu ihrem bezaubernden Gesang zurück.\n\nUnd dann, auf der blühenden, lieblichen Wiese,\nbeim zarten Rauschen von Laub und Zweigen,\nschläft der Ziegenhirt, den treuen Hund an der Seite.\n\nZum fröhlichen Klang des Dudelsacks\ntanzen Nymphen und Hirten unter dem lieben Himmel,\nwenn der Frühling strahlend erscheint.", "hinweis": "Das Sonett steht in der Erstausgabe von 1725 über den Noten und wird Vivaldi selbst zugeschrieben; die altertümliche Schreibweise ist original."},
    "hoeren":[{"text": "Auf YouTube anhören", "url": "https://www.youtube.com/results?search_query=Vivaldi+Vier+Jahreszeiten+Fr%C3%BChling+La+primavera", "spotify": "Vivaldi Vier Jahreszeiten Frühling"}]},
  {"id": "SD503", "titel": "Vivaldis Sommer – mit Gedicht", "text": "Im „Sommer“ lähmt die Hitze alles, bis ein Gewitter mit Hagel losbricht. Lies das Gedicht und hör dann, wann der Kuckuck ruft und wann es donnert.", "min": 11, "tf": "ABCD", "kat": "Musik", "haltung": "im Sitzen, im Liegen", "t": "musik",
    "gedicht":{"titel": "Sonett zum „Sommer“ (L'Estate)", "autor": "Antonio Vivaldi zugeschrieben, 1725", "original": "Sotto dura Staggion dal Sole accesa\nLangue l' huom, langue 'l gregge, ed arde il Pino;\nScioglie il Cucco la Voce, e tosto intesa\nCanta la Tortorella e 'l gardelino.\n\nZeffiro dolce Spira, mà contesa\nMuove Borea improviso al Suo vicino;\nE piange il Pastorel, perche sospesa\nTeme fiera borasca, e 'l suo destino;\n\nToglie alle membra lasse il Suo riposo\nIl timore de' Lampi, e tuoni fieri\nE de mosche, e mosconi il Stuol furioso!\n\nAh che pur troppo i Suoi timor Son veri\nTuona e fulmina il Ciel e grandinoso\nTronca il capo alle Spiche e a' grani alteri.", "deutsch": "In der harten Jahreszeit, von der Sonne entflammt,\nermattet der Mensch, ermattet die Herde, und die Kiefer glüht.\nDer Kuckuck erhebt seine Stimme, und gleich danach\nsingen die Turteltaube und der Distelfink.\n\nEin sanfter Westwind weht, doch plötzlich\nfordert ihn der Nordwind zum Kampf heraus.\nUnd der junge Hirte weint, denn bang\nfürchtet er den wilden Sturm und sein Schicksal.\n\nSeinen müden Gliedern raubt die Ruhe\ndie Angst vor Blitzen und wildem Donner\nund der wütende Schwarm von Fliegen und Bremsen.\n\nAch, seine Furcht ist nur zu berechtigt:\nDer Himmel donnert und blitzt, und der Hagel\nschlägt den Ähren und dem stolzen Korn die Köpfe ab.", "hinweis": "Das Sonett steht in der Erstausgabe von 1725 über den Noten und wird Vivaldi selbst zugeschrieben; die altertümliche Schreibweise ist original."},
    "hoeren":[{"text": "Auf YouTube anhören", "url": "https://www.youtube.com/results?search_query=Vivaldi+Vier+Jahreszeiten+Sommer+L%27estate", "spotify": "Vivaldi Vier Jahreszeiten Sommer"}]},
  {"id":"SD309","titel":"Zunehmend oder abnehmend?","text":"Schau heute Abend nach dem Mond und bestimm mit einem alten Trick, ob er zu- oder abnimmt. Danach prüfst du im Kalender, ob du recht hattest.","min":5,"tf":"ABCD","kat":"Sinne","haltung":"im Sitzen, im Stehen","t":"licht",
    "optionen":["Rundung links, wie „(“: mit einem Strich wird daraus ein „a“ – abnehmend","Rundung rechts, wie „)“: mit einem Strich wird daraus ein „z“ – zunehmend","Ganz rund: Vollmond","Nicht zu sehen: Neumond oder Wolken"]},
  {"id":"SD310","titel":"Herbstblätter bestimmen","text":"Sammel beim nächsten Gang fünf verschiedene Blätter und bestimm, von welchem Baum sie stammen. Die Form verrät es.","min":15,"tf":"ABC","kat":"Sinne","haltung":"im Sitzen, unterwegs","t":"natur",
    "optionen":["Eiche: gebuchtete Lappen, kurzer Stiel","Rotbuche: glattrandig, oval, leicht gewellt","Ahorn: Hand mit fünf spitzen Fingern","Birke: klein, dreieckig, gesägter Rand","Linde: herzförmig, schief am Ansatz","Kiefer: keine Blätter, sondern Nadeln zu zweit"]},
  {"id":"SD311","titel":"Apfel-Verkostung","text":"Kauf drei Apfelsorten, schneid sie auf und verkoste sie mit geschlossenen Augen. Wer gewinnt bei Süße, Säure und Knack?","min":10,"tf":"ABC","kat":"Sinne","haltung":"im Sitzen","t":"goennen"},

  /* ---------- Lernen, Listen, Hände, Kontakt – Teil 2 ---------- */
  {"id":"SD312","titel":"Mal elf im Kopf","text":"Zweistellige Zahlen mal elf rechnest du in einer Sekunde: Ziffern auseinanderziehen, Summe in die Mitte. 34 × 11 = 3 (3+4) 4 = 374. Probier fünf Aufgaben und verblüff jemanden damit.","min":5,"tf":"ABC","kat":"Lernen","haltung":"im Sitzen, im Liegen","t":"gelernt"},
  {"id":"SD313","titel":"Römische Jahreszahlen","text":"Lern, wie man römische Zahlen liest, und entziffer die Jahreszahl an einem Gebäude oder auf einem alten Buch. MCMXLVI ist zum Üben.","min":10,"tf":"ABC","kat":"Lernen","haltung":"im Sitzen, im Liegen","t":"gelernt",
    "optionen":["I = 1","V = 5","X = 10","L = 50","C = 100","D = 500","M = 1000","Steht ein kleiner Wert vor einem größeren, wird er abgezogen: IV = 4, XC = 90"]},
  {"id":"SD314","titel":"Dein Name in Morsezeichen","text":"Lern, wie dein Name im Morsealphabet klingt, und klopf ihn auf den Tisch. Bonus: Schreib Max eine Nachricht nur aus Punkten und Strichen.","min":10,"tf":"ABC","kat":"Lernen","haltung":"im Sitzen, im Liegen","t":"gelernt",
    "optionen":["R: · – ·","I: · ·","T: –","A: · –"]},
  {"id":"SD315","titel":"Dieses Jahr zum ersten Mal","text":"Schreib eine Liste von allem, was du dieses Jahr zum ersten Mal gemacht hast. Der Voi-Roller steht schon drauf.","min":10,"tf":"ABC","kat":"Listen","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD316","titel":"Fragen, die ich klären will","text":"Sammel zehn Fragen, auf die du schon immer eine Antwort wolltest, von „Warum ist der Himmel blau?“ bis „Wie funktioniert ein E-Roller?“. Eine pro Tag wird geklärt, gern mit ChatGPT.","min":10,"tf":"ABC","kat":"Listen","haltung":"im Sitzen, im Liegen","t":"tagebuch"},
  {"id":"SD317","titel":"Zehn Ausflüge mit dem Bus","text":"Schreib zehn Ziele auf, die du mit Bus und Bahn von Spandau aus erreichen kannst und noch nie gesehen hast. Die BVG-App sagt dir, wie lange es jeweils dauert.","min":15,"tf":"ABC","kat":"Listen","haltung":"im Sitzen","t":"tagebuch"},
  {"id":"SD319","titel":"Rezept-Tausch im Haus","text":"Frag jemanden im Haus nach dem Lieblingsrezept und biete deins im Tausch an. Wer zuerst nachkocht, hat gewonnen.","min":10,"tf":"ABC","kat":"Kontakt","haltung":"im Stehen","t":"nachbar"},
  {"id":"SD320","titel":"Eine Karte aus Spandau nach Schweden","text":"Schick Daniel und Familie eine echte Postkarte aus Spandau – mit drei Sätzen auf Schwedisch als Überraschung. Für eine Karte nach Schweden reicht eine internationale Briefmarke von der Post.","min":15,"tf":"ABC","kat":"Kontakt","haltung":"im Sitzen","t":"brief"},

  /* ---------- Kreativ ---------- */
  {"id":"SD321","titel":"Collage: Die Illustrierte dreht durch","text":"Schneid aus einer Illustrierten fünf Figuren aus und kleb sie zu einer völlig absurden Szene zusammen, mit Sprechblasen. Material: alte Zeitschrift, Schere, Klebestift, ein Blatt Papier.","min":30,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit",
    "schritte":["Zeitschrift durchblättern und fünf Figuren ausschneiden: Promis, Models, ein Hund aus der Werbung – alles gilt.","Einen Hintergrund suchen: Landschaft, Küche, Autobahn.","Figuren so kleben, dass eine unmögliche Szene entsteht: der Ministerpräsident beim Ballett, die Königin auf dem Voi.","Sprechblasen ausschneiden und beschriften. Foto an Max."]},
  {"id":"SD322","titel":"Klecks-Monster","text":"Ein Tropfen Wasserfarbe aufs Papier, mit dem Strohhalm in alle Richtungen pusten – und aus jedem Klecks wird mit Filzstift ein Monster mit Augen und Namen. Material: Wasserfarbe, Pinsel, Strohhalm, schwarzer Stift.","min":20,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit",
    "schritte":["Einen dicken, nassen Farbtropfen aufs Papier setzen.","Mit dem Strohhalm darüber pusten, damit Arme und Beine entstehen.","Trocknen lassen.","Mit dem schwarzen Stift Augen, Zähne und Hüte dazumalen. Jedes Monster bekommt einen Namen."]},
  {"id":"SD323","titel":"Blind gezeichnet: Max","text":"Zeichne Max nach einem Foto, ohne aufs Papier zu schauen. Bei Blindzeichnungen gibt es kein Falsch: Künstler machen das als Übung, und die Linien werden oft überraschend lebendig.","min":10,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit"},
  {"id":"SD324","titel":"Zentangle: Muster bis zum Rand","text":"Zeichne ein Quadrat, teil es mit drei Bleistiftlinien in Felder und füll jedes Feld mit einem anderen Muster: Wellen, Schuppen, Punkte, Gitter. Material: Fineliner, Papier, Bleistift.","min":20,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit",
    "optionen":["Wellen","Schuppen","Punkte in Reihen","Gitter mit ausgemalten Kästchen","Spiralen","Treppen","Kreise in Kreisen"]},
  {"id":"SD325","titel":"Postkarten-Collage","text":"Bastel eine Postkarte als Collage: Spandau-Motive aus der Zeitung vorn, drei Sätze auf Schwedisch hinten. Material: Karton im Postkartenformat (10,5 × 14,8 cm), Schere, Kleber.","min":30,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit"},
  {"id":"SD326","titel":"Malen mit Tee und Kaffee","text":"Schwarzer Tee, Rooibos und Kaffee geben drei wunderbare Brauntöne. Mal damit eine Landschaft oder einen alten Schatzplan. Material: Teebeutel, kalter Kaffee, Pinsel, dickes Papier.","min":20,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit",
    "schritte":["Starken Tee und Kaffee kochen und abkühlen lassen.","Mit dem Pinsel oder direkt mit dem Teebeutel tupfen.","Mehrere Schichten machen es dunkler.","Ränder leicht anreißen – fertig ist die Schatzkarte."]},
  {"id":"SD327","titel":"Kartoffeldruck","text":"Eine halbe Kartoffel, ein Messer, Farbe – und du hast einen Stempel. Druck damit Geschenkpapier, eine Karte oder ein Muster für dein Tagebuch.","min":25,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit",
    "schritte":["Eine große Kartoffel halbieren, Schnittfläche trocken tupfen.","Mit einem Kugelschreiber eine einfache Form aufmalen: Herz, Stern, Tannenbaum, Fisch.","Rund um die Form etwa 1 cm tief wegschneiden.","Mit dem Pinsel Farbe auftragen und fest aufs Papier drücken."]},
  {"id":"SD328","titel":"Fingerabdruck-Figuren","text":"Drück den Daumen auf ein Stempelkissen und dann aufs Papier – aus jedem Abdruck wird mit dem Stift ein Tier oder eine Figur. Ein ganzer Zoo in zehn Minuten.","min":10,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit",
    "optionen":["Maus: Abdruck, zwei Ohren, Schwanz","Marienkäfer: roter Abdruck, Punkte","Vogel: Abdruck, Schnabel, Beinchen","Schaf: viele kleine Abdrücke, Kopf dazu","Hühnchen: gelber Abdruck, Kamm, Füße"]},
  {"id":"SD329","titel":"Blätter drucken","text":"Bemal die Rückseite eines Herbstblattes mit Farbe und drück es aufs Papier. Die Adern erscheinen wie gestochen. Material: Blätter, Wasser- oder Acrylfarbe, Pinsel.","min":20,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit"},
  {"id":"SD330","titel":"Das eigene Mandala","text":"Zeichne mit Teller, Glas und Eierbecher Kreise ineinander und füll die Ringe mit Mustern. Dann ausmalen – es ist dein eigenes Ausmalbild, kein gekauftes.","min":30,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit"},
  {"id":"SD331","titel":"Eine Tagebuchseite als Kunstwerk","text":"Gestalte eine Doppelseite im Tagebuch zum heutigen Tag: Überschrift in Schmuckschrift, ein Ausschnitt aus der Zeitung, eine Skizze, ein Fundstück. Später schlägst du genau diese Seite am liebsten auf.","min":25,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"tagebuch"},
  {"id":"SD332","titel":"Ein Bild in fünf Minuten","text":"Stell den Timer auf fünf Minuten und mal, was gerade vor dir liegt. Wenn es klingelt, ist Schluss, auch mitten im Strich. Signieren nicht vergessen.","min":5,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit"},
  {"id":"SD333","titel":"Selbstporträt nach Art eines Meisters","text":"Mal dich selbst im Stil eines berühmten Malers: mit Picassos zwei Nasen, Van Goghs Wirbeln oder Warhols knalligen Farben. Ein Handspiegel hilft.","min":30,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit",
    "optionen":["Picasso: Gesicht von vorn und von der Seite zugleich","Van Gogh: alles in kurzen, wirbelnden Strichen","Warhol: dasselbe Gesicht viermal, jedes in anderen Knallfarben","Matisse: aus buntem Papier geschnitten statt gemalt","Modigliani: langer Hals, mandelförmige Augen"]},
  {"id":"SD334","titel":"Die Farbmisch-Tabelle","text":"Mal mit nur drei Farben – Rot, Gelb, Blau – eine Tabelle aller Farben, die du daraus mischen kannst. Wie viele Brauntöne schaffst du?","min":20,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit",
    "schritte":["Ein Gitter mit 5 × 5 Kästchen zeichnen.","Oben und links die drei Grundfarben eintragen.","In jedes Kästchen eine Mischung aus Zeile und Spalte malen, mal mehr, mal weniger von einer Farbe.","Die schönste Mischung bekommt einen eigenen Namen."]},
  {"id":"SD335","titel":"Schwarzweiß-Foto wird bunt","text":"Such ein Schwarzweiß-Foto aus der Zeitung und mal es mit Buntstiften so bunt an, wie du willst. Der Kanzler mit lila Haaren ist ausdrücklich erlaubt.","min":15,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit"},
  {"id":"SD336","titel":"Ein Buchcover für den Feuerkelch","text":"Entwirf dein eigenes Titelbild für den „Feuerkelch“: Was ist für dich das wichtigste Motiv? Titel und Name der Autorin in Schmuckschrift dazu.","min":25,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit"},
  {"id":"SD337","titel":"Wortbild","text":"Schreib ein Wort so, dass es aussieht wie das, was es bedeutet: „Regen“ in tropfenden Buchstaben, „Wind“ verweht, „Spandau“ mit Zinnen. Drei Wörter, ein Blatt.","min":15,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit"},
  {"id":"SD338","titel":"Steine bemalen","text":"Bemal einen flachen Stein vom Weg mit Acrylfarbe: als Marienkäfer, Gesicht oder Muster. Danach legst du ihn irgendwo in Spandau aus, für einen Finder.","min":25,"tf":"ABC","kat":"Kreativ","haltung":"im Sitzen","t":"handarbeit"}
];
